programs.sol:
"""Approximate a predominantly lexical response to the number three.

Recognize numeral forms, cardinal/ordinal words, Roman III, and Chinese
three-compounds. Fixed scores also cover Wednesday and March. ASCII 3
is stronger after letters, weaker in decimals, times, and repeated 3s.
A smaller side response covers ability/caution adjectives, especially
following forms of 'be'. Everything else receives zero: the component's
remaining small lexical responses are intentionally not tabulated.
"""
import unicodedata

READS = ()
THREE_WORDS = {'three', 'trois', 'três', 'drei'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    new_document = (prefix.position == 0 or
                    prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if new_document else prefix.token_strings[-2]

    if token == '3':
        char = previous[-1:]
        if new_document:
            value = 1.067
        elif char.isalpha():
            value = 1.18
        elif char == '3':
            value = 0.79
        elif char.isdigit():
            value = 0.91
        elif char == '.':
            value = 0.85
        elif char == ':':
            value = 0.83
        elif char.isspace():
            value = 0.88
        else:
            value = 0.94
    elif token == '三':
        value = 1.08
    elif len(token) == 1 and unicodedata.numeric(token, None) == 3:
        value = {'³': 1.02, '₃': 1.45}.get(token, 0.95)
    elif word in THREE_WORDS:
        value = 1.08 if word == 'three' else 0.85
    elif word == 'tres' and raw[:1].isspace():
        value = 0.70
    elif word in {'third', 'thirds', 'треть'}:
        value = 1.01
    elif word in {'thirty', 'thirteen'}:
        value = 0.78
    elif word == '-three':
        value = 1.50
    elif word in {'-third', '-thirds'}:
        value = 1.15
    elif token == 'III':
        value = 0.84
    elif token == 'iii':
        value = 0.63
    elif token == '第三':
        value = 1.18
    elif '三' in token:
        value = 0.75
    elif word == 'wednesday':
        value = 0.84
    elif word == 'march' and token[:1].isupper():
        value = 0.33
    elif raw[:1].isspace() and word in {'able', 'careful', 'sure', 'aware'}:
        before = previous.strip().lower()
        if before in {'be', 'being', 'been'}:
            value = 0.65 if word != 'aware' else 0.40
        else:
            value = 0.35 if word == 'able' else 0.15
    elif '\ufffd' in raw:
        # A token may contain just the last byte of a Unicode numeral.
        char = prefix.text_prefixes[-1][-1:]
        if char and unicodedata.numeric(char, None) == 3:
            value = 1.45 if char == '₃' else 1.0
        else:
            value = 0.0
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Component layers.0.mlp.down_proj:5504: a "the number three" detector.

It is silent on almost every token. It fires on the digit 3 (and its ³, ３, ₃
forms) at about 0.9, and on words for three (three, third, trois, drei, tres,
三, 第三) at about 1.0. Roman III and "thirty" get about 0.8, and "Wednesday"
(the third weekday in some calendars) about 0.9. Each prediction depends only on
the newest token, so no state is carried between positions.
"""

READS = ()

THREE_DIGITS = {"3", "³", "３", "₃"}
THREE_WORDS = {"three", "third", "thirds", "trois", "drei", "tres", "三", "第三", "三个", "周三"}
ROMAN_OR_TENS = {"iii", "thirty"}


def step(carry, prefix, upstream):
    # Strip spaces and hyphens so " three", "-third" and " 3" all match.
    tok = prefix.token_strings[-1].strip(" -").lower()
    if tok in THREE_DIGITS:
        return carry, 0.92
    if tok in THREE_WORDS:
        return carry, 1.0
    if tok in ROMAN_OR_TENS:
        return carry, 0.8
    if tok == "wednesday":
        return carry, 0.9
    return carry, 0.0

programs.luna:
"""Approximate the component as a pulse on written forms of three."""

READS = ()

THREE_WORDS = {
    "three", "third", "thirty", "threes",
    "tres", "três", "trois", "drei", "dritte",
    "три", "третья", "三", "三つ", "三番目",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()
    if token == "3" or token in THREE_WORDS:
        return None, 0.9
    return None, 0.0

"""Approximate a small first-layer signal for public recognition and appreciation.

The strongest cues are award names and award-giving words; weaker cues are
thanks, honors, distinction, and commemorations.  Most tokens carry no signal.
"""

READS = ()

AWARDS = {
    "award", "awards", "awarded", "awarding", "prize", "prizes",
    "medal", "medals", "trophy", "trophies", "oscar", "oscars",
    "grammy", "grammys", "pulitzer", "nobel", "laureate", "laureates",
    "honorary", "award-winning",
