    "honours", "commendation", "commendations", "commend",
    "commemorate", "commemorative", "memorial", "memorials",
    "monument", "monuments", "紀念", "纪念", "賞", "栄誉", "受賞",
}

THANKS = {
    "thank", "thanks", "thanked", "thanking", "thankful", "thankfulness",
    "gratitude", "grateful", "appreciate", "appreciated", "appreciation",
    "congratulate", "congratulated", "congratulations",
}

DISTINCTION = {
    "distinguished", "notable", "notably", "illustrious", "eminent",
    "prestigious", "renowned", "recognition", "recognized", "recognised",
    "reputation", "accomplished", "achievement", "achievements",
    "contribution", "contributions", "meritorious", "title", "career",
    "fame", "famous", "recipient", "receive", "received", "winner",
    "winners", "win", "won", "remarkable", "named", "earned",
}

ASIAN_AWARDS = {
    "奖", "獎", "获奖", "獲獎", "颁奖", "頒獎", "获奖作品", "奖励", "獎勵",
    "荣誉", "榮譽", "荣获", "榮獲", "荣光", "荣耀", "榮耀", "勋章", "勳章",
    "奖牌", "獎牌", "賞", "受賞", "栄誉",
}

ASIAN_HONORS = {
    "盛誉", "盛譽", "声誉", "聲譽", "赞扬", "讚揚", "表彰", "认可", "認可",
    "杰出", "傑出", "纪念", "紀念", "感謝", "感谢", "感激", "感恩", "勲章",
    "顕彰", "功績", "記念",
}

_EDGE = " \t\r\n.,!?;:'\"()[]{}<>…—–-_/\\"


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip(_EDGE)
    if word in AWARDS:
        value = 2.8
    elif word in ASIAN_AWARDS:
        value = 2.5
    elif word in THANKS or word in ASIAN_HONORS:
        value = 1.6
    elif word in HONORS:
        value = 1.8
    elif word in DISTINCTION:
        value = 1.0
    else:
        value = 0.0
    return None, float(value)

