import re
READS = ()
def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.lstrip(" \t\n\"'([{.-_")
    low = w.lower()
    if re.match(r"(sc|sk|sch|ск)", low):
        n = len(w)
        base = -4.0 if n <= 2 else (-2.6 if n == 3 else -1.4)
        if w[:2].isupper():
            base *= 1.3
    elif re.match(r"(esc|asc|desc)", low):
        base = -2.5
    elif re.match(r"s[nmqzbvf]", low):
        base = -0.4
    else:
        base = 0.0
    return carry, base

programs.sol:
"""Approximate a spelling feature for T at the start of a token's word.

Most T-initial words get a positive response, larger for capitals. TH and TR
are weaker than TU. Common grammatical words and number words are weak or
silent; time/test inflections have separate strengths. Lowercase fragments
continuing a word and contraction endings are suppressed. Control tags and
the printed tab escape have explicit responses. The same rule recognizes
several other alphabets' T letters and Japanese T-row syllables.

This deliberately ignores most individual-word and contextual variation.
"""
READS = ()

NEUTRAL = frozenset('''
the that this these those they them their theirs themselves there than
therefore
'''.split())


def response(token, previous):
    if token in ("'t", '’t'):
        return -0.2
    if token == '</tool_call>':
        return 0.13
    if token in ('<think>', '</think>'):
        return -0.1 if token == '<think>' else 0.07
    if token == '<tool_call>':
        return 3.07
    if token == '<tool_response>':
        return 1.4
    if token == '</tool_response>':
        return -0.18
    if token == '\\t':
        return 1.29
    word = token.lstrip().lstrip('.,/<>=(_-\\\"\'@[{*:')
    if not word:
        return 0.0
    lower = word.lower()
    if lower == 'th' and previous[-1:].isdigit():
        return 0.14
    if lower in ('two', 'three', 'third', 'twenty', 'thirty'):
        return 0.35 if word[0].isupper() else 0.07
    if lower == 'to':
        return 0.6 if word[0].isupper() else 0.0
    if lower in ('until', 'although'):
        return 0.56
    if lower in NEUTRAL:
        return 0.0 if lower != 'therefore' else 0.16
    # An unspaced lowercase fragment after a letter is usually a word ending.
    continuation = (token == word and previous and
                    previous[-1].isalpha() and word[0].islower())
    if continuation:
        return 0.0
    if word.startswith(('t', 'T')):
        value = 1.55
        if lower.startswith('tr'):
            value = 1.2
        if lower.startswith('tu'):
            value = 1.95
        if lower.startswith('th'):
            value = 0.85
        if word[0].isupper():
            value += 0.45
        if lower in ('then', 'thus', 'though', 'through', 'throughout'):
            value = 0.75
        if lower in ('total', 'totals', 'together'):
            value = 0.95 if lower == 'together' else 1.2
        if lower in ('time', 'times'):
            value = (1.15 if lower == 'time' else 0.65)
            if word[0].isupper():
                value += 0.5
        if lower in ('test', 'tests'):
            if token[:1].isspace():
                value = 1.9 if lower == 'test' else 1.5
            else:
                value = 2.2 if lower == 'test' else 2.4
        if lower == 't':
            value = 2.05 if word == 'T' else 1.55
            if previous.endswith("'"):
                value = 0.0
        return value
    # Arabic's definite article can precede the T letter.
    if word.startswith('الت'):
        return 2.5
    if word.startswith('ت'):
        if token == word and previous[-1:].isalpha():
            return 0.4
        return 1.9
    if word.startswith(('т', 'Т', 'τ', 'Τ', 'ת')):
        return 1.6
    if word[0] in 'ทตถ':
        return 1.5
    if word[0] in 'たちつてとタチツテト':
        if word.startswith('として'):
            return 0.1
        return 0.7 if word == 'と' else 1.3
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    return (document, token), float(value)

"""Approximate the component's soft-C spelling sensitivity.

Across a token seam (ac|etic, C|iv), C followed by E/I/Y gives a positive
signal. A/O/R continuations tend negative, with weaker negatives for U/L/H.
Longer pieces weaken these signals; the second letter's class adjusts them.
A token beginning CE/CI/CY after leading separators has a smaller positive
cue. Case and vowel accents are ignored, but C must be the literal letter.
State resets between documents. This is not a pronunciation dictionary;
smaller lexical and multilingual responses are deliberately left unmodeled.
"""
import unicodedata

READS = ()
STOP_CONSONANTS = frozenset('bptdgk')


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1].lower()
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if previous.endswith('c') and token:
        first, second = plain(token[0]), plain(token[1:2])
        length = min(len(token), 7) - 2
        previous_length = min(len(previous.strip()), 7) - 1
        if first in ('e', 'i', 'y'):
            value = 2.60 - 0.32 * length - 0.24 * previous_length
            if first == 'y':
                value -= 0.23
            if second in ('a', 'o', 'u'):
                value -= 0.25
            if second in STOP_CONSONANTS:
                value += 0.31
            if previous[0].isspace():
                value += 0.13
            value = max(0.0, value)
        elif first in ('a', 'o', 'r', 'u', 'l', 'h'):
            if first == 'a':
                value = -0.67
            elif first == 'o':
                value = -1.00
            elif first == 'r':
                value = -0.68
            else:
                value = -0.27
            value += 0.05 * length + 0.03 * previous_length
            if second in ('m', 'n', 'r'):
                value -= 0.26
            value = min(0.0, value)
    else:
        word = token.lstrip(' \t\n-./')
        if (len(word) >= 2 and word[0] == 'c'
                and plain(word[1]) in ('e', 'i', 'y')):
            value = 0.85 * 0.65 ** max(0, len(word) - 2)
    return (doc, token), value

"""A document-opening response, strongest for chat headers.

The first token is generally negative. Punctuation, single letters and digits
are stronger than words; sentence-opening 'The' and 'This' have the opposite
sign. After that, the response is small, except for the first chat role name.
Message endings are positive, but negative after tool-call/response closers.
These are coarse token classes, not a vocabulary lookup.
"""
READS = ()


def opening(token):
    word = token.strip()
    if token == '<|im_start|>':
        return -1.038
    if '\ufffd' in token:
        return 0.0
    if token == 'The':
        return 0.261
    if token == 'This':
        return 0.173
    if word.isdecimal():
        return -0.329
    if token.isspace():
        return -0.34 if len(token) == 1 else -0.265
    if word in {'.', ',', '。', '，'}:
        return -0.54 if token == word else -0.25
    if word in {'a', 'an'}:
        return -0.48 if token.startswith(' ') else -0.23
    if word in {'the', 'and', 'or', 'of', 'in', 'to', 'is', 'was',
                'are', 'that', 'with', 'by', 'on'}:
        return -0.30
    if word and set(word) <= {'#'}:
        return -0.10 if len(word) == 1 else -0.03
    if word in {'-', '//'}:
        return -0.12
    if word == '|':
        return -0.02
    if len(word) == 1 and word.isalpha():
        return -0.29 if word.isascii() else -0.15
    if word and all(not c.isalnum() for c in word):
        return -0.32
    return -0.16


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, 1, token), opening(token)
    _, position, previous = carry
    value = -0.025 if position == 1 else 0.005
    if token == '<|im_end|>':
        value = -0.24 if previous in {
            '</tool_call>', '</tool_response>'
        } else 0.084
    elif token in {'</tool_call>', '</tool_response>'}:
        value = 0.07
    if position == 1 and previous == '<|im_start|>':
        value = -0.30 if token == 'user' else -0.45
    return (doc, position + 1, token), value

programs.haiku:
"""layers.0.mlp.down_proj:5509, a diffuse layer-0 MLP output direction.

Mostly near zero with small noise; what it does reliably is:
- the first token of every packed row sits at about -0.22 (attention sees only itself);
- a chat-template <|im_start|> directly after <|endoftext|> gives a fixed -1.04;
- <|im_end|> closing a tool call/response is negative (-0.23), one closing a sentence
  (after '.', '?', ...) is positive (+0.14), other <|im_end|> slightly negative;
- 'user' right after <|im_start|> is slightly negative (-0.09);
- a word-piece continuation after a short fragment ending in 'ar' (e.g. 'Mar'+'oon',
  'Har'+'riet') is positive, about +0.19 on average.
Everything else is predicted as 0.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    prev = s[-2] if len(s) > 1 else ""
    if prefix.position == 0:
        return None, -0.22
    if cur == "<|im_start|>" and prev == "<|endoftext|>":
        return None, -1.04
    if cur == "<|im_end|>":
        if prev in ("</tool_response>", "</tool_call>"):
            return None, -0.23
        if prev in (".", "?", "。", ")."):
            return None, 0.14
        return None, -0.05
    if cur == "user" and prev == "<|im_start|>":
        return None, -0.09
    if re.fullmatch(r"[A-Za-z]{0,3}ar", prev.strip(), re.I) and cur[:1].isalpha() and not cur.startswith(" "):
        return None, 0.19
    return None, 0.0

programs.luna:
"""Capture the component's reset-position response and common opening markers.

It is most negative at the start of a fresh text sequence, especially for the
chat-start marker, and returns close to zero after the first token or two.
"""

READS = ()


def step(carry, prefix, upstream):
    """Use document age, plus recognizable text openers, as a small approximation."""
    document = prefix.document_ids[-1]
    if carry is None or document != carry[0]:
        age = 0
    else:
        age = carry[1] + 1

    token = prefix.token_strings[-1]
    if age == 0:
        if token == "<|im_start|>":
            value = -1.038
        elif token == ".":
            value = -0.589
        elif token == ",":
            value = -0.509
        elif token.strip() == "(":
            value = -0.510
        elif token == " a":
            value = -0.492
        else:
            value = -0.25
    elif age == 1:
        value = -0.04
    else:
        value = 0.0
    return (document, age), float(value)

programs.sol:
"""Predict responses to space-separated punctuation and 'absolute value'.

Stops following words are stronger than stops following numbers or
single-letter variables. Dots have separate responses for dot leaders and
line endings. A French-function-word heuristic lowers colon, semicolon and
question-mark responses. Operators, brackets and quotes have weaker responses.
Dot-containing path fragments and 'absolute value(s)' also get positive
estimates. Other tokens
receive zero: this leaves many small lexical activations unexplained.
"""
import re

READS = ()

# Context columns: word, number/variable, blank, attached stop, spaced stop, other.
PROSE_STRENGTH = {',': 0.84, ';': 0.60, ':': 0.31, '?': 0.39}
CONTEXT_GAIN = (1.0, 0.15, 0.60, 1.65, 0.65, 0.70)
DOT = (1.47, 0.46, 1.15, 1.76, 0.45, 1.20)
SLASH = (0.14, -0.05, 0.12, 0.47, 0.17, 0.12)
DOT_LINE_END = (0.53, 0.26, 0.43, 0.80, 0.17, 0.52)
DOT_PARAGRAPH_END = (0.86, 0.34, 0.61, 0.94, 0.21, 0.72)
FRENCH = set('le la les des du une un et que qui pour avec dans vous votre est '
             'sont sur ce cette au aux pas par mais nous ne elle ils elles '
             'peut être'.split())
ENGLISH = set('the and a to of for with is are that this it we they you on in '
              'by at from'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    token = prefix.token_strings[-1]
    next_carry = (doc, token, (recent + token)[-160:])
    if not token.startswith(' ') and token not in ('/.', '().'):
        if token.strip().lower() not in ('value', 'values'):
            return next_carry, 0.0
    p = previous.strip()
    match = re.search(r'\w+$', recent)
    word = match.group() if match else ''
    if not p:
        context = 2
    elif p[-1].isdigit() or (word.isalpha() and len(word) == 1
                            and word not in ('a', 'I')):
        context = 1
    elif p in ('.', ',', ':', ';'):
        context = 4 if previous.startswith(' ') else 3
    elif p[-1].isalpha():
        context = 0
    else:
        context = 5
    value = 0.0
    if token.startswith(' '):
        mark = token[1:].strip()
        mark = {'：': ':', '，': ','}.get(mark, mark)
        if mark in PROSE_STRENGTH or mark in ('.', '/'):
            if mark == '.':
                value = DOT[context]
            elif mark == '/':
                value = SLASH[context]
            else:
                value = PROSE_STRENGTH[mark] * CONTEXT_GAIN[context]
            if mark == '.' and '\n' in token:
                values = DOT_PARAGRAPH_END if '\n\n' in token else DOT_LINE_END
                value = values[context]
            elif '\n' in token:
                value *= 0.85
            if mark in (':', ';', '?'):
                words = re.findall(r"[a-zàâçéèêëîïôûùüÿœ]+", recent.lower())
                french = sum(w in FRENCH for w in words)
                english = sum(w in ENGLISH for w in words)
                if french >= 2 and french > english + 1:
                    value -= {':': 0.20, ';': 0.27, '?': 0.34}[mark]
        elif mark in ('-', '+', '|', '%'):
            value = (0.01, -0.04, 0.06, 0.20, 0.10, 0.07)[context]
        elif mark in (')', ']'):
            value = (0.10, -0.14, 0.12, 0.40, 0.12, 0.10)[context]
        elif mark in ('"', "'", '['):
            value = (-0.03, -0.08, 0.03, 0.06, 0.02, 0.01)[context]
        elif mark == './':
            value = 0.35
        elif mark and set(mark) == {'.'}:
            value = 0.05 if len(mark) == 3 else 0.44
    if token == '/.':
        value = 0.46
    if token.strip().lower() in ('value', 'values') and word.lower() == 'absolute':
        value = 0.64
    return next_carry, float(value)

programs.luna:
"""Give a small score to punctuation preceded by whitespace."""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token[:1].isspace():
        rest = token.lstrip()
        if rest and unicodedata.category(rest[0]).startswith("P"):
            return None, 0.05
    return None, 0.0

programs.sol:
"""Approximate a response to Unicode typography.

Fullwidth Latin letters/digits, subscripts, and italic/bold mathematical
letters receive large negative estimates. Continuing a fullwidth run
strengthens its response. Other fonts, raised numerals, Arabic/Persian
digits, and a few typographic punctuation marks have separate estimates.
Ordinary text gets small script/length averages and two chat-marker values.
Split glyphs are recognized by a UTF-8 prefix or a newly completed character.
"""
import unicodedata as ud

READS = ()
# These are byte-prefix tokens, not a learned table of word activations:
SUBSCRIPT_OR_CURRENCY_PREFIX = 15896  # UTF-8 E2 82: U+2080..U+20BF
SUPPLEMENTARY_SYMBOL_PREFIXES = {56252, 81250}  # F0 9D, space + F0 9D


def wide(c):
    return '０' <= c <= '９' or 'Ａ' <= c <= 'Ｚ' or 'ａ' <= c <= 'ｚ'


def variant(c, in_run, fragment):
    name = ud.name(c, '')
    if wide(c):
        if c == '０':
            base = -0.48
        elif c == '１':
            base = -0.37
        elif c.isdigit():
            base = -0.41
        else:
            base = -0.55 if c.isupper() else -0.43
