"""Approximate an adapting text-boundary response, not ordinary word identity.

Line breaks are strongest near a document's start, before other newline tokens.
Attached sentence punctuation boosts them. Letter-heavy and Han-character lines
get boosts; source-like syntax and an initial chat marker damp early breaks.
Document ends depend on earlier breaks. JSON, code fences, chat/tool/thinking
markers, numeric types and input/output words have separate fitted responses.
All other tokens predict zero. State resets at each document boundary.
"""
import math
import re

SOURCE_SYNTAX = re.compile(r"\b(?:import|include|def|class|package)\b|[{};=]")

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, "", token == "<|im_start|>")
    _, position, breaks, line, chat = carry
    value = 0.0

    if '\n' in token:
        newline_count = token.count('\n')
        head = token.split('\n', 1)[0]
        line += head
        ending = head.strip()
        if ending and ending[-1] in '.。':
            offset, amplitude, adaptation = 0.0233, 0.7051, -0.1267
        elif ending and ending[-1] in '!?！？':
            offset, amplitude, adaptation = 0.0487, 0.6177, -0.1233
        elif ending and ending[-1] in ':：':
            offset, amplitude, adaptation = 0.0673, 0.3288, -0.0826
        elif not ending:
            offset, amplitude, adaptation = -0.0150, 0.5771, -0.0227
        else:
            offset, amplitude, adaptation = 0.0211, 0.3608, -0.0422
        rise = 0.095 + 0.905 * (1 - math.exp(-position / 3.89))
        novelty = rise / (1 + position / 16.97) ** 0.764
        novelty /= 1 + 1.958 * breaks
        familiarity = position / (position + 87.66) * breaks / (breaks + 1)
        value = offset + amplitude * novelty + adaptation * familiarity
        # Prose amplifies an early break; source syntax and chat framing damp it.
        letters = sum(c.isalpha() for c in line)
        prose = letters / max(len(line), 1)
        han_fraction = sum('\u3400' <= c <= '\u9fff' for c in line) / max(letters, 1)
        value += 0.068 * prose * novelty
        value += han_fraction * (0.033 + 0.050 * novelty)
        if chat:
            value -= 0.211 * novelty
        if SOURCE_SYNTAX.search(line):
            value -= 0.115 * novelty
        if newline_count >= 2:
            value += 0.011 - 0.110 * novelty
        if ending.startswith('`') and newline_count >= 2:
            value += 0.18
        elif ending.endswith('|'):
            value += 0.06
        elif ending.endswith('>'):
            value += 0.04
        elif ending.endswith(('}', ']', ';', ',')):
            value += -0.02 if newline_count == 1 else 0.02
        elif not ending and token.startswith((' ', '\t')):
            value -= 0.025
        if ending == '。':
            value += 0.025
        breaks += 1
        line = token.rsplit('\n', 1)[-1]
    elif token == '{"':
        value = -0.321
    elif token == ' {"':
        value = -0.069
    elif token == '(':
        value = -0.084 if position else 0.083
    elif token.strip() in ('``', '```'):
        value = -0.098 if len(token.strip()) == 2 else -0.231
    elif token == ' `':
        value = -0.057
    elif token == '<tool_call>':
        value = -0.144
    elif token in ('<tool_response>', '</tool_response>'):
        value = 0.14 - 0.5 / math.sqrt(position + 10)
    elif token in ('<think>', '</think>'):
        value = -0.09 - 0.32 / math.sqrt(position + 8)
    elif token == '<|endoftext|>':
        value = -0.266 + 0.538 / (1 + 0.598 * breaks)
        value -= 0.288 / (1 + position / 9.35)
    elif token.strip() in ('input', 'output'):
        value = -0.158 if token.startswith(' ') else -0.10
    elif token.strip() in ('int', 'float', 'double', 'bool'):
        value = -0.09 if token.startswith(' ') else -0.12
    elif token == '<|im_start|>':
        value = 0.06 - 0.26 / math.sqrt(1 + position / 3)
    elif token == '<|im_end|>':
        value = -0.17 / math.sqrt(1 + position / 10)
    if '\n' not in token:
        line = (line + token)[-1000:]
    return (doc, position + 1, breaks, line, chat), float(value)

