"""A lexical response to paired/contrastive clauses and backslash-quoted text.

English 'both/either/neither' and several corresponding Chinese and European
clause markers give negative activations. The Chinese character 既 has an
especially strong response, even in its 'already' sense. Escaped quotation
marks give a positive response, reduced when joined to closing punctuation.
Articles immediately after English pair markers retain a weaker echo.
'Already' and 'existing' share the weaker pre-existence response; the
conditional 'unless' has a small positive response.
Unlisted tokens are approximated by zero; no token-ID lookup is used.
"""
READS = ()

# Pairing, addition ('not only'), concession, and alternative-clause markers.
CLAUSE_MARKERS = {
    'both': -1.02,
    'either': -0.55,
    'neither': -1.00,
    'tanto': -0.68,
    'både': -2.05,
    'zwar': -1.21,
    '既': -6.90,
    '既然': -2.50,
    '不仅': -2.52,
    '不僅': -2.52,
    '不但': -2.02,
    '虽然': -0.64,
    '雖然': -0.58,
    '虽': -0.94,
    '雖': -0.96,
    '一旦': -0.62,
    '一方面': -0.90,
    '无论是': -0.88,
    '不论是': -0.84,
    'zarówno': -3.00,
    'unless': 0.29,
}


def escaped_quote(token):
    before, _, after = token.partition('\\"')
    value = 1.19
    if before.isspace():
        value += 0.12
    if before.endswith('('):
        value -= 0.15
    if before.endswith('='):
        value -= 0.07
    if before.endswith('{'):
        value -= 0.17
    if before.endswith('}'):
        value -= 0.40
    if before.endswith('.'):
        value -= 0.28
    if '"' in before or "'" in before:
        value -= 0.58
    if before.endswith('\\'):
        value -= 1.04
    if '\\"' in after:
        return max(0.0, value - 0.39)
    if after.startswith((',', ':', '\\')):
        value -= 0.51
    elif after.startswith((')', ']', '>')):
        value -= 0.67
    elif after:
        value -= 0.30
    if len(after) > 1:
        value -= 0.20
    return max(0.0, value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = CLAUSE_MARKERS.get(word, 0.0)
    if word in {'both', 'neither'} and token.strip()[:1].isupper():
        value += 0.10 if word == 'both' else 0.25
    if word.startswith('既') and word not in CLAUSE_MARKERS:
        value = -5.5
    if word.startswith(('不仅', '不僅')) and word not in CLAUSE_MARKERS:
        value = -2.0
        if word.endswith('是'):
            value = -1.46
        elif '仅仅' in word:
            value = -1.13
    if word == 'existing':
        value = -0.35
    elif word == 'already':
        value = -0.14
    if word == 'ohl' and previous == 'sow':
        value = -0.92  # The last token of German 'sowohl' (both).
    if '\\"' in token:
        value = escaped_quote(token)
    elif token.strip() == "\\'":
        value = 0.63
    elif previous in {'both', 'either', 'neither'}:
        if word == 'the':
            value = -0.66 if previous == 'both' else -0.27
        elif word in {'a', 'an'}:
            value = -0.40 if previous == 'both' else -0.20
        elif word == 'of':
            value = -0.26 if previous == 'both' else -0.08
        elif word == 'in' and previous == 'both':
            value = -0.14
    return (doc, word), float(value)

