"""Negative pulses at recognizable document openings.

Source-file headers (imports, declarations and comments) fire most strongly;
markup headings and common English sentence openers also fire. Only the
first token of each document receives a pulse; all other predictions are zero.
Case and leading spaces matter: these rules match whole decoded tokens.
This approximates the large boundary response, not interior lexical variation.
"""
READS = ()


def opening(s):
    if s in ('import', 'from'):
        return -5.2
    if s == 'package':
        return -3.27
    if s == 'export':
        return -2.64
    if s == 'using':
        return -1.78
    if s in ('class', 'def', 'function', 'print'):
        return -1.64
    if s in ('const', 'module', 'namespace', 'require'):
        return -1.2
    if s in ('let', 'var'):
        return -0.95
    if s in ('public', 'private'):
        return -2.0
    if s in ('The', 'This'):
        return -1.05
    if s == 'What':
        return -2.22
    if s == 'How':
        return -1.54
    if s == 'In':
        return -0.88
    if s in ('We', 'If', 'An', 'You'):
        return -0.64
    if s in ('A', 'It', 'There', 'When'):
        return -0.51
    if s in ('Title', '---\n'):
        return -4.08  # Title label or YAML front matter.
    if s.startswith('#!/'):
        return -4.46
    if s == '#include':
        return -2.72
    if s in ('#ifndef', '#pragma', '#from'):
        return -1.23
    if s in ('#', '##', '###'):
        return -2.3
    if s.startswith('/*'):
        if s.count('*') > 2:
            return -1.8  # Decorative comment separator.
        return -4.4 if '\n' in s else -2.51
    if s == '//':
        return -1.62
    if s in ('"""\n', "'''\n"):
        return -4.84 if s[0] == '"' else -3.19
    if s in ('"""', "'''"):
        return -1.75
    if s == '<?':
        return -2.89
    if s == '<':
        return -3.54
    if s == '\\':
        return -1.61
    if s == '```':
        return -0.56
    return 0.0


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    first = carry is None or carry != doc
    value = opening(prefix.token_strings[-1]) if first else 0.0
    return doc, value

