"""Give restrained negative cues to familiar kinds of text opening.

This component is normally close to silent.  Harvested high-impact examples
are concentrated at the start of a packed document: Markdown headings, source
code declarations, and a small set of common English sentence openers.  The
rules intentionally ignore other openings and all interior tokens.
"""
READS = ()
SCALE = 0.9

CODE_OPENERS = {"package", "from", "def", "class", "module", "import"}
ENGLISH_OPENERS = {
    "the", "a", "an", "this", "that", "what", "when", "if", "in", "use",
}

def step(carry, prefix, upstream):
    t = prefix.position
    opening = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not opening:
        return None, 0.0

    word = prefix.token_strings[t].strip()
    if word.startswith("#!"):
        return None, SCALE * -4.4
    if word.startswith("#include"):
        return None, SCALE * -2.7
    if word.startswith("#"):
        return None, SCALE * -2.2
    if word.lower() in CODE_OPENERS:
        return None, SCALE * -2.2
    if word.lower() in ENGLISH_OPENERS:
        return None, SCALE * -0.8
    return None, 0.0

