"""Approximate a path/indentation feature using visible text.

Path-opening slashes and directory/folder vocabulary are negative; slashes
joined to alphabetic path segments are usually mildly positive. Tabs followed
by spaces are strongly negative at deeper indentation. A short text tail
separates file-path contexts from arithmetic and ordinary uses of 'path'.
Carriage returns also respond negatively, especially without preceding text.
Most unrelated token-specific responses are intentionally left at zero.
"""
import re

READS = ()
FILES = re.compile(
    r'\b(?:files?|paths?|director(?:y|ies)|folders?|filesystem|working|'
    r'rootdir|cachedir|command|interpreter|image)\b|'
    r'\b(?:cd|cat|find|ls|grep|python)(?: -[\w-]+)*\s*$', re.I
)
DIRECTORY_WORDS = {
    'directory', 'directories', 'folder', 'folders', '目录', 'каталог',
}


def response(s, tail):
    if s.startswith('\t') and s[1:] and s[1:].strip(' ') == '':
        n = len(s) - 1
        if n <= 4:
            return -0.13
        if n <= 6:
            return -0.30
        return -0.65 if n in (7, 15) else -0.52
    if s == ' /':
        if not tail:
            return -0.51
        if re.search(r'[\d)}\]]\s*$', tail):
            return -0.65
        return -1.02 if FILES.search(tail[-100:]) else -0.88
    if s.startswith('#!'):
        return -0.20
    if '/' in s and s.count('/') == 1 and '<' not in s and '*' not in s:
        before, after = s.split('/')
        if after.isascii() and after.isalpha() and not before:
            if after in {'test', 'tests', 'fixtures', 'utils'}:
                return 0.0
            return 0.08 if len(after) <= 2 else 0.17
        if not any(c.isalnum() for c in s):
            if not before:
                return -0.14 if tail[-1:].isdigit() else -0.20
            if after or '.' in before:
                return -0.25
            if before.endswith(')'):
                return -0.37
            return -0.61
    if s == '／':
        return -0.53
    word = s.strip(' ._-').lower()
    if word in DIRECTORY_WORDS:
        return -0.81 if s.startswith(' ') and word == 'directory' else -0.57
    if word == 'filesystem':
        return -0.65 if not s.startswith(' ') else -0.18
    if word in {'dir', 'dirs'}:
        code_context = FILES.search(tail) or tail.endswith(('root', 'cache', 'temp'))
        return -0.47 if code_context else -0.17
    if word in {'path', 'paths'}:
        return -0.22 if FILES.search(tail) else 0.02
    if word in {'drive', 'disk'} and re.search(r'\bhard\s*$', tail, re.I):
        return -0.68
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_doc = carry is None or carry[0] != doc
    tail = '' if new_doc else carry[1]
    only_returns = True if new_doc else carry[2]
    s = prefix.token_strings[-1]
    if s == '\r':
        value = -0.60 if only_returns else -0.16
    else:
        value = response(s, tail)
    if '\ufffd' in s and prefix.text_prefixes[-1].endswith('／'):
        value = -0.75
    only_returns = only_returns and s == '\r'
    return (doc, (tail + s)[-200:], only_returns), float(value)

