import unicodedata

READS = ()

SINGULAR_SUBJECT = {"i", "ich", "io", "je", "yo", "eu", "я", "我"}
PLURAL_SUBJECT = {"we", "wir", "nous", "nosotros", "nosotras", "noi", "nós", "мы", "我们", "我們"}
OTHER_FIRST_PERSON = {
    "me", "my", "mine", "myself", "us", "our", "ours", "ourselves",
    "mich", "mir", "mein", "meine", "meiner", "meinen", "uns", "unser",
    "mi", "mí", "mío", "mía", "nos", "nuestro", "nuestra", "nosso",
    "nossa", "mon", "ma", "mes", "moi", "notre",
}


def punctuation(char):
    return unicodedata.category(char).startswith("P")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    current_doc = prefix.document_ids[-1]
    previous_char = "" if carry is None or carry[0] != current_doc else carry[1]
    starts_word = (
        not previous_char
        or previous_char.isspace()
        or punctuation(previous_char)
        or raw[:1].isspace()
        or (raw and punctuation(raw[0]))
    )
    word = raw.strip().lower()
    while word and punctuation(word[0]):
        word = word[1:]
    while word and punctuation(word[-1]):
        word = word[:-1]
    if starts_word and word in SINGULAR_SUBJECT:
        value = -0.82
    elif starts_word and word in PLURAL_SUBJECT:
        value = -0.54
    elif starts_word and word in OTHER_FIRST_PERSON:
        value = -0.73
    else:
        value = 0.0
    tail = raw[-1:] if raw else previous_char
    return (current_doc, tail), value

