    'cette': 0.55, 'ce': 0.1, 'toute': 1.2, 'toutes': 1.2,
    'que': 0.95, 'qu': 1.1, 'en': 0.85, 'par': 1.5, 'et': -0.2,
    'est': -0.15, 'si': 1.25, 'plus': 0.8, 'bien': 1.2,
    'encore': 0.65, 'aussi': 0.75, 'donc': 0.65, 'même': 0.65,
    'également': 0.65, 'qui': -0.2, 'se': -0.25, 'on': -0.35,
    'a': -0.25, 'de': -0.1, 'ne': 0.3, 'sur': 0.25,
    'pendant': 0.4, 'trop': 0.65, 'tous': 0.45, 'quant': 0.35,
}
DISTINCTIVE_FRENCH = frozenset(
    'une cette elle elles lui cela toute toutes encore aussi donc même '
    'également'.split()
)
FEMININE_WORDS = frozenset(
    'grande petite bonne belle nouvelle première dernière nue ouverte faite '
    'vie place suite part prison lecture parole fin cause fille'.split()
)
FEMININE_ENDINGS = (
    'ine', 'ines', 'ante', 'antes', 'uve', 'uves', 'ute', 'utes',
    'erte', 'ertes', 'ise', 'ises', 'ive', 'ives',
)
SOFT_ENDINGS = (
    'ance', 'ances', 'ire', 'ires', 'able', 'ables', 'ible', 'ibles',
    'ure', 'ures', 'ale', 'ales',
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        evidence, proof = 0.0, 0.0
    else:
        evidence, proof = carry[1] * 0.97, carry[2] * 0.98
    s = prefix.token_strings[-1]
    raw = s.strip()
    w = raw.lower().lstrip("'’")
    boundary = s[:1].isspace() or s[:1] in "'’" or s[:1].isupper()
    if boundary and w in FRENCH:
        evidence = min(4.0, evidence + 1.0)
    elif boundary and w in OTHER:
        evidence = max(0.0, evidence - 1.5)
    if any(c in s for c in 'éèêëàâçîïôùûœ'):
        evidence = min(4.0, evidence + 0.7)
    french = min(1.0, max(0.0, evidence - 0.5) / 1.5)
    if boundary and w in DISTINCTIVE_FRENCH:
        french = 1.0

    if raw in ('theorem', 'lemma', 'simp', 'rw') or any(c in s for c in '⊢✝'):
        proof = min(4.0, proof + 2.0)
    elif raw in ('Type', 'Prop', 'case', 'inst'):
        proof = min(4.0, proof + 1.0)

    value = 0.0
    if s == ' →':
        value = 0.45 if proof >= 2.0 else 0.03
    elif boundary and w in GRAMMAR:
        value = GRAMMAR[w] * french
        if w in ('la', 'en', 'par', 'que') and raw[:1].isupper():
            value *= 0.6
    elif w in ('quelle', 'quelles', 'laquelle', 'lesquelles'):
        value = 1.55 * french
    elif boundary and w in FEMININE_WORDS:
        value = 1.05 * french
    elif w.endswith(('ique', 'iques', 'ment', 'ments', 'aire', 'aires')):
        pass
    elif w.endswith(('que', 'ques')):
        value = 0.45 * french
    elif w.endswith(('ue', 'ues')):
        value = 1.05 * french
    elif w in ('ite', 'ites'):
        value = 1.35 * french
    elif w.endswith(('elle', 'elles', 'use', 'uses')):
        value = 0.95 * french
    elif w.endswith(FEMININE_ENDINGS + ('ite', 'ites')):
        value = 0.65 * french
    elif w.endswith(('ée', 'ées')):
        value = 0.4
    elif w.endswith(('ie', 'ies')):
        value = 0.55 * french
    elif w.endswith(SOFT_ENDINGS):
        value = (0.25 if boundary else 0.45) * french
    elif w in ('ant', 'ants', 'ent', 'ents', 'at', 'ats') and not boundary:
        value = -0.45 * french
    elif w in ('e', 'es') or s in ("'", '’'):
        value = 0.25 * french
    elif len(w) == 1 and w.isascii() and w.isalpha() and not raw.isupper():
        value = 0.15 * french
    elif w == '-':
        value = 0.4 * french
    return (doc, evidence, proof), float(value)

programs.luna:
"""A small lexical sketch of a selective French function-word signal.

In the sampled text, la, elle, une, cette, en, and que tend positive,
while le, un, et, and qui tend negative. This predicts only a modest
word-level cue, not a general French-language detector.
"""

READS = ()

POSITIVE_FRENCH_CUES = {
    "la", "elle", "elles", "une", "cette", "en", "que", "l", "plus",
}
NEGATIVE_FRENCH_CUES = {"le", "un", "et", "qui", "on"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in POSITIVE_FRENCH_CUES:
        return None, 0.15
    if word in NEGATIVE_FRENCH_CUES:
        return None, -0.06
    return None, 0.0

programs.sol:
"""A lexical detector of names, words, and their interpretation.

Predict negative activations for naming and linguistic vocabulary, especially
in 'the name/word/term' and 'given/family/common name'. Weaken code-like uses;
exclude word counts, 'in other words', and ordinal mathematical terms.
Use only the current and previous token, resetting at document boundaries.
The numbers are rounded approximations to training-data activation averages.
"""
READS = ()

NAME_TYPES = set('given family personal proper real original scientific '
                 'generic ancient trade brand full middle'.split())
CODE = set('file function variable domain host class field module parameter '
           'param table column attribute interface method string'.split())
LANGUAGES = set('latin greek hebrew arabic german french english tamil '
                'italian chinese sanskrit japanese welsh'.split())
COUNTS = set('one two three four five six seven eight nine ten hundred '
             'thousand million'.split())
ORDINALS = set('first second third fourth fifth next last each'.split())

# Related naming, meaning, and notation vocabulary.
LEXICAL = {
    'named': -1.1, 'renamed': -1.2, 'nicknamed': -1.3,
    'nickname': -2.3, 'surname': -1.9, 'alias': -0.9,
    'designation': -0.9, 'denomination': -0.8, 'terminology': -2.1,
    'meaning': -1.0, 'meanings': -1.3, 'means': -0.6, 'mean': -0.2,
    'literally': -0.9, 'phrase': -1.5, 'phrases': -1.0,
    'pronunciation': -2.1, 'spelling': -1.3, 'spelled': -1.6,
    'acronym': -1.8, 'synonym': -1.8, 'synonyms': -1.6,
    'abbreviation': -1.6, 'coined': -2.1,
    'symbol': -0.8, 'symbols': -0.6, 'notation': -0.8,
    'prefix': -0.8, 'suffix': -1.5, 'plural': -1.2,
    'noun': -1.3, 'nouns': -1.4, 'verb': -0.5, 'typo': -0.6,
    'called': -0.35, 'referred': -0.5,
    'latin': -1.4, 'greek': -1.3, 'hebrew': -1.0,
    'nombre': -1.1, 'namen': -1.1, 'nome': -0.9, 'nom': -0.6,
    'wort': -0.6,
}
CJK = {  # Naming, speech, and meaning in Chinese/Japanese characters.
    '名': -1.15, '名称': -1.2, '名稱': -1.2, '名字': -2.2,
    '命名': -1.4, '含义': -1.9, '音': -0.85, '意': -0.7,
    '語': -0.7, '语': -0.5, '称': -0.3, '稱': -0.7, '叫': -0.6,
}
BASE = {'name': -2.0, 'names': -1.9, 'word': -1.2, 'words': -0.6,
        'term': -0.8, 'terms': -0.4, 'title': -0.4}
DEFINITE = {'name': -3.45, 'names': -3.0, 'word': -3.05,
            'words': -1.3, 'term': -3.15, 'terms': -1.4, 'title': -1.4}


def activation(token, previous):
    raw, prior = token.strip(), previous.strip()
    word, prev = raw.lower(), prior.lower()
    spaced = token[:1].isspace()
    syntax = not prior or any(c in prior for c in '{}=<>();,\"+:')
    if word in BASE:
        if not spaced:
            return -0.7 if raw == 'NAME' else (-0.15 if raw == 'Name' else -0.35)
        if word in {'name', 'names'} and raw != word:
            return (-2.5 if prev == 'the' else -1.2) if raw.isupper() else -0.8
        if prev == 'the':
            return DEFINITE[word] * (1.25 if prior == 'The' else 1.0)
        if word in {'name', 'names'}:
            if prev == 'common':
                return -5.7
            if prev in NAME_TYPES or prev in LANGUAGES:
                return -3.0
            if prev in CODE or syntax:
                return -0.4 if word == 'name' else -0.9
            if prev in {'first', 'last'}:
                return -0.7
        if word in {'word', 'words'} and prev in LANGUAGES:
            return -5.3 if prev in {'latin', 'greek', 'hebrew', 'english'} else -3.5
        if word == 'word' and (syntax or prev in CODE or
                               prev in {'if', 'for', 'first', 'last', 'in'}):
            return -0.2
        if word == 'words':
            if prev.isdigit() or prev in COUNTS:
                return 0.25
            if prev in {'other', 'of'}:
                return -0.1
        if word in {'term', 'terms'}:
            if prev in ORDINALS:
                return 0.45 if prev == 'first' else 0.0
            if prev == 'in' and word == 'terms':
                return 0.2
            if prev == 'long':
                return 0.2
        return BASE[word]
    if raw in CJK:
        if raw in {'名', '名称', '名稱', '名字'}:
            if prev == '中文':
                return -4.6
            if prev.isdigit():  # 名 as a counter for people, not a name.
                return -0.45
            if prev in {'文件', '主机', '函数', '表', '类'}:
                return -0.3
        return CJK[raw]
    # The Greek naming suffix -onym, etymology and nomenclature may be split.
    joined = prev + word if not spaced else word
    if word in {'onym', 'onyms'}:
        return -2.1 if word == 'onym' else -3.0
    if 'etymolog' in joined or 'nomencl' in joined:
        return -2.4
    if raw == 'ˈ':  # IPA primary-stress mark.
        return -1.2
    if word == 'for' and prev in {'name', 'word', 'term', 'named', 'names'}:
        return -0.8
    if raw in {'"', '“', "'"} and prev in {'name', 'word', 'term'}:
        return -1.1
    value = LEXICAL.get(word, 0.0)
    return value if spaced else value * 0.55


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), float(activation(token, previous))

"""Approximate the component as a comma pulse with repetition suppression.

Training responses were dominated by commas, with weaker responses when
commas were close together. The pulse depends on the comma's script and
characters sharing its token: quotes, brackets, newlines or attached words.
Recent commas weaken the negative pulse over a five-token distance scale.
For ordinary commas, suppression is weaker after compound commas or
intervening periods, question/exclamation marks or newlines. There are
first-comma, document-start and preceding-digit adjustments.
Memory resets between documents; non-comma tokens give zero.
"""
import math

READS = ()
COMMAS = ',，、،'


def comma_kind(text):
    """Classify a comma by the ordinary characters sharing its token."""
    text = text.strip(' \t')
    i = next((j for j, ch in enumerate(text) if ch in COMMAS), -1)
    if i < 0:
        return None
    left, right = text[:i], text[i + 1:]
    if right.startswith(('\r', '\n')):
        base = -0.63 + 0.15 * (text.count('\n') >= 2) + 0.17 * bool(left)
        return 'newline', base, 0.33
    if right and right[0].isascii() and (right[0].isalnum() or right[0] == '_'):
        return 'attached_word', -3.51, 0.62
    if right and not right[0].isascii() and right[0].isalnum():
        return 'attached_word', -0.39, 0.62
    if not left and not right:
        if text == ',':
            return 'plain', -1.47, 1.55
        return 'international', -1.22 if text == '、' else -1.12, 0.33
    if text[i] != ',' and right:
        return 'compound', -0.60, 0.20
    if not right:
        if left.endswith('.'):
            base = -0.77
        elif left.endswith(('"', "'", '”', '’', '»')):
            base = -0.81
        elif left.endswith((')', ']', '}')):
            base = -1.03
        elif left.endswith(('$', '%', '`', '>')):
            base = -1.21
        else:
            base = -1.01
    elif not left:
        if right[0] in '\"\'“”‘’':
            base = -1.22
        elif right[0] in '\\/@':
            base = -2.40
        else:
            base = -2.27
    else:
        base = -1.67
    return 'compound', base, 0.62


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, None, True, -1, '')
    _, position, last_comma, last_plain, last_boundary, previous = carry
    text = prefix.token_strings[-1]
    kind = comma_kind(text)
    value = 0.0
    if kind is not None:
        name, base, suppression = kind
        gap = position - last_comma if last_comma is not None else 10000
        recency = 1.0 / (1.0 + (gap / 5.0) ** 2)
        value = base + suppression * recency
        if last_comma is None:
            value -= 0.15
            if name == 'plain':
                value -= 0.28 / math.sqrt(max(position, 1))
        if name == 'plain':
            if not last_plain:
                value -= 0.51 * recency
            if last_boundary > (last_comma if last_comma is not None else -1):
                value -= 0.63 * recency
            if previous.strip().isdigit():
                value -= 0.09
        if position == 0:
            value = 0.0
        elif position == 1:
            value += 0.76
        elif position == 2:
            value += 0.17
        last_comma = position
        last_plain = name == 'plain'
    if any(ch in text for ch in '.!?。！？\n'):
        last_boundary = position
    state = (doc, position + 1, last_comma, last_plain, last_boundary, text)
    return state, float(value)

"""Approximate a list-separator comma signal, not all lexical activation noise.

A comma is strongest shortly after an unmatched opening delimiter or an import
keyword. The signal fades with token distance. Nearby enclosing delimiters add
strength. Commas fused with other text behave differently from standalone ones.
Small adjustments use the preceding number, single-letter variable, or sentence
adverb. All tokens without a comma are predicted as zero. State resets for each
document; quotes are not parsed, so brackets inside quoted code still count.
"""
import math
import re

READS = ()
OPEN = '([{（［｛<'
PAIRS = dict(zip(')]}）］｝>', OPEN))
SENTENCE_ADVERBS = {
    'however', 'therefore', 'nevertheless', 'nonetheless', 'respectively',
    'instead', 'thus', 'moreover', 'furthermore', 'otherwise', 'though',
}
# Offset and opening-strength adjustment for non-standalone comma tokens.
COMMA_FORMS = {
    'line_end': (-0.02429, -0.30107),
    'leading_or_quoted': (-0.08213, -0.57215),
    'after_close': (-0.07004, -0.56290),
    'embedded': (-0.10495, -0.65631),
}


def fade(age):
    return 1.0 / (1.0 + (max(age - 1, 0) / 4.0) ** 1.5)


def comma_value(pos, chars, stack, previous, line, importpos, form):
    value = 0.00451
    strength = 0.0
    if stack:
        kind, start, charstart, attached, lastcomma = stack[-1]
        strength = fade(pos - start)
        scale = 0.68270 + 0.59979 / (pos + 1)
        scale += 0.12743 if kind in '[［' else 0.0
        scale += 0.06152 if kind in '{｛' else 0.0
        scale -= 0.21732 if kind == '<' else 0.0
        scale += 0.06359 * attached
        scale -= 0.01417 * math.log1p(chars - charstart)
        value += scale * strength
        value += 0.12037 * sum(fade(pos - q[1]) for q in stack[:-1])
        if lastcomma >= 0:
            value += 0.04280 * fade(pos - lastcomma)
    if re.search(r'\bimport\b', line) or re.search(r'\buse\s+\S*::', line):
        value += 0.88395 * fade(pos - importpos)
    match = re.search(r'(\w+)\W*$', previous)
    word = match.group(1) if match else previous.strip()
    if word.isdecimal():
        value += 0.04380
    elif word.isascii() and word.isalpha() and len(word) == 1:
        value += 0.07508
    if word.lower() in SENTENCE_ADVERBS:
        value -= 0.18534 if word.islower() else 0.03809
    if form in COMMA_FORMS:
        offset, adjustment = COMMA_FORMS[form]
        value += offset + adjustment * strength
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, [], '', '', -1000)
    _, pos, chars, stack, previous, line, importpos = carry
    if re.search(r'\bimport\b', text) or text.strip() == 'use':
        importpos = pos

    before_comma = text.split(',', 1)[0]
    if text.strip() == ',' and '\n' not in text:
        form = 'standalone'
    elif text.startswith(',') and ('\n' in text or '\\n' in text):
        form = 'line_end'
    elif before_comma.strip('\\\"\' ') == '':
        form = 'leading_or_quoted'
    elif any(ch in PAIRS for ch in before_comma):
        form = 'after_close'
    else:
        form = 'embedded'

    value = 0.0
    seen_comma = False
    for offset, char in enumerate(text):
        before = (line + text[:offset])[-1:]
        if char in OPEN:
            attached = before and (before.isalpha() or before in '_:>')
            following = text[offset + 1:offset + 2]
            if char != '<' or (attached and following not in ('<', '=')):
                attached = bool(before and (before.isalnum() or before in '_]'))
                stack.append([char, pos, chars + offset, attached, -1000])
        elif char in PAIRS:
            for j in range(len(stack) - 1, -1, -1):
                if stack[j][0] == PAIRS[char]:
                    stack = stack[:j]
                    break
        elif char == ',' and not seen_comma:
            value = comma_value(pos, chars + offset, stack, previous,
                                line + text[:offset], importpos, form)
            seen_comma = True
            if stack:
                stack[-1][4] = pos
    if '\n' in text or '\\n' in text:
        importpos = -1000
    line = re.split(r'\n|\\n', line + text)[-1][-200:]
    carry = (doc, pos + 1, chars + len(text), stack, text, line, importpos)
    return carry, float(value)

programs.luna:
"""Mark commas inside parentheses, brackets, or braces as list separators."""
READS = ()

OPEN = "([{"
CLOSE = ")]}"


def step(carry, prefix, upstream):
    depth, old_doc = carry if carry is not None else (0, None)
    doc = prefix.document_ids[-1]
    if doc != old_doc:
        depth = 0
    inside = False
    for char in prefix.token_strings[-1]:
        if char in OPEN:
            depth += 1
        elif char in CLOSE:
            depth = max(0, depth - 1)
        elif char == "," and depth:
            inside = True
    return (depth, doc), 0.2 if inside else 0.0

"""Recognize words about definitions and boundaries, plus C code markers.

The stronger cues are words like "defined" and "boundary".  A smaller
negative cue covers limits, divisions, related Chinese words, and common C
preprocessor, string, and memory functions.  Other tokens predict zero.
"""

READS = ()

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold().strip()

    if "#define" in word:
        return None, -8.0
    if "#pragma" in word:
        return None, -1.6
    if any(s in word for s in ("boundary", "boundar", "border", "bounded")):
        return None, -1.6
    if "definit" in word:
        return None, -0.75
    if "defin" in word:
        return None, -1.8
    if any(s in word for s in ("bound", "limit", "interface", "outline")):
        return None, -0.9
    if any(s in word for s in ("divide", "division", "divided", "dividing")):
        return None, -0.6
    if any(s in word for s in ("sizeof", "strlen", "fgets")):
        return None, -0.7
    if any(s in word for s in ("#include", "sprintf", "malloc")):
        return None, -0.4
    if any(s in word for s in ("finite", "无限", "界", "定义")):
        return None, -0.8
    return None, 0.0

programs.sol:
"""Small lexical-and-grammar approximation of a weak early-layer component.

Most predictions are near zero. The rule retains the rare upheaval/DUI and
Chinese-infringement responses, then adds common grammatical-word biases,
control/typographic-token biases, and a few 'of'/'to' phrase constructions.
Opening-position offsets reset whenever the document changes. Coefficients
are rounded training estimates; unrecognized tokens get a near-zero baseline.
These are partial lexical regularities, not a unified topic detector.
"""
READS = ()

# Each row is a recognizable word class with a shared fitted activation.
WORD_CLASSES = (
    (0.036, {'any', 'some', 'many', 'much'}),           # quantifiers
    (-0.030, {'each', 'every', 'both'}),               # distributives
    (0.075, {'still', 'further', 'never'}),            # persistence/extension
    (0.023, {'you', 'he', 'him', 'she', 'her', 'who'}), # personal/relative pronouns
    (-0.010, {'we', 'us', 'our', 'their'}),
    (0.010, {'be', 'been', 'is', 'was', 'has'}),        # auxiliaries
    (-0.024, {'must', 'shall', 'should'}),             # obligation modals
    (0.030, {'because', 'although'}),                 # clause connectors
    (-0.036, {'while', 'unless'}),
    (-0.037, {'within', 'without', 'around', 'across', 'down'}),
    (-0.065, {'very', 'various', 'particular', 'general', 'actual'}),
    (-0.079, {'shown', 'produce', 'produced', 'done', 'started', 'stop', 'stopped'}),
)
DOMAINS = {'domain', 'domains', 'realm', 'realms', 'sector', 'sectors'}


def lexical(token):
    word = token.strip()
    lower = word.lower()
    if lower in {'uphe', 'upheaval', 'upheavals'}:
        return 0.70
    if word == 'DUI':
        return 0.48
    if word in {'侵犯', '侵害'}:
        return -0.62
    if word == '侵权':
        return -0.38
    if '领域' in word:
        return -0.35
    if lower == 'interests':
        return -0.31
    if lower in DOMAINS:
        return -0.17
    if word in {'.LEADING', '.TRAILING'}:               # GUI alignment constants
        return -0.59
    if word in {'</think>', '</tool_call>'}:
        return -0.12
    if word in {'<|im_end|>', '<|endoftext|>', '<tool_call>'}:
        return -0.023
    if token == '\r':
        return -0.10
    if token == '\t':
        return -0.014
    if word == r'\n':
        return 0.028
    if word and all(c in '¹²³⁴⁵⁶⁷⁸⁹⁰' for c in word):
        return -0.04
    if word in {'✓', '✔', '✅'}:
        return -0.09 if token.startswith(' ') else -0.03
    if word in {'⇒', '··'}:
        return -0.08
    if token == ' –':
        return -0.039
    if lower == 'beyond':
        return 0.14
    if lower == 'same':
        return 0.042
    if lower == 'also':
        return 0.025
    if lower == 'an':
        return 0.014
    for value, words in WORD_CLASSES:
        if lower in words:
            return value
    return -0.0015


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    position = 0 if reset else carry[2] + 1
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = lexical(token)
    if word == 'of':
        if previous in DOMAINS | {'interests', 'field', 'world'}:
            value = -0.20
        elif previous in {'range', 'variety', 'majority', 'couple', 'area', 'each'}:
            value = -0.09
