    word = s.strip().lower()
    if s.startswith(" ") and word in AREA:
        return -0.2
    if s.startswith(" ") and word in OFFICE:
        return 0.1
    if SCRIPT.search(s):
        return -0.007
    if CODE.search(s):
        return -0.011
    return 0.0


