programs.sol:
"""Predict quotation punctuation, apostrophe-s endings, and 'some' tokens.

Escaped and typographic quotes are strong; code/list separators and line-ending
quote bundles are weaker. The previous token distinguishes a prose opening
from indentation or adjacent strings. Apostrophe-s is suppressed after common
contraction bases and irregular person-plurals. Selected quote shapes also
use separation from earlier marks, the recent mark count, and properties of
the previous token. The word 'all' and the end-of-thinking tag have separate
responses. All memory resets at document boundaries.
"""
import math

READS = ()
CONTRACTIONS = {'it', 'that', 'there', 'here', 'what', 'where', 'who', 'how', 'let'}
PEOPLE = {
    'man', 'woman', 'child', 'boy', 'girl', 'father', 'mother', 'parent',
    'brother', 'sister', 'son', 'daughter', 'husband', 'wife', 'person',
    'patient', 'user', 'student', 'teacher', 'veteran', 'singer', 'friend',
}
PLURAL_PEOPLE = {'men', 'women', 'children', 'people'}
CODE_WORDS = {'return', 'case', 'echo', 'print', 'include', 'import', 'from'}
ARTICLES = {'the', 'a', 'an', 'this', 'that'}
# Character-level punctuation classes, not a vocabulary-token lookup.
TYPOGRAPHIC = {
    '“': 0.72, '”': 1.17, '«': 0.03, '»': 0.97,
    '「': 0.60, '」': 1.12, '『': 0.56, '』': 0.58,
    '《': 0.56, '》': 0.39, '‘': 0.59, '’': 0.37,
}
MARKS = frozenset(TYPOGRAPHIC) | frozenset("\"'„")


def opening_quote(previous, single=False):
    if any(c in previous for c in "\"'"):
        return -0.12
    p = previous.strip()
    if not p:
        return 0.0 if single else -0.05
    if p in ARTICLES:
        return 0.95 if single else 1.3
    if p.lower() in CODE_WORDS:
        return 0.3
    if p in ('and', 'or'):
        return 0.6 if single else 0.75
    if p.replace('_', '').isalpha():
        return 0.75 if single else 1.1
    if p in ',:.':
        return ({',': 0.27, ':': 0.2, '.': 0.57} if single else
                {',': 0.74, ':': 0.49, '.': 0.62}).get(p, 0.35)
    return 0.25 if single else 0.35


def strength(token, previous):
    s = token.strip()
    space, newline = token[:1].isspace(), '\n' in token or '\r' in token
    if s.lower() in ('some', 'all'):
        return (0.74 if s[:1].islower() else 0.8) if s.lower() == 'some' else 0.1
    if s == '</think>':
        return 0.61
    if s in ("'s", '’s'):
        p = previous.strip().lower()
        if p in CONTRACTIONS:
            value = -0.05
        elif p in ('he', 'she'):
            value = -0.16
        elif p in PLURAL_PEOPLE:
            value = -0.27
        elif p in PEOPLE and previous[:1].isspace():
            value = 0.30
        else:
            value = 0.53
        return value - (0.04 if s[0] == '’' else 0.0)
    if s in ("'t", '’t', "'re", '’re', "'m", '’m', "'d", '’d'):
        return -0.03
    if s in ("'ve", "'ll", '’ve', '’ll'):
        return 0.09 if s[0] == "'" else 0.01
    if '\\"' in s:
        after = s.rsplit('\\"', 1)[-1]
        if after:
            return 0.74 if after == '\\' else 0.55
        return 1.44 if s.startswith('(') else 1.31 if space else 1.12
    for char, value in TYPOGRAPHIC.items():
        if char not in s:
            continue
        if space:
            value += -0.2 if char == '»' else 0.3
        if s != char:
            if char == '’' and any(c.isalpha() for c in s):
                return 0.0
            value *= 0.8 if s.startswith(char) else 0.45
            if char == '”' and s.startswith('”)'):
                value = 0.22
        return value * (0.55 if newline else 1.0)
    if '„' in s:
        return 0.45
    if '"' in s:
        if s.count('"') >= 3:
            return 0.03 if newline else 0.15
        if s.count('"') >= 2:
            return 0.55
        if s == '"':
            return opening_quote(previous) if space else 0.1 if newline else 0.71
        before, after = s.split('"', 1)
        if newline:
            return 0.22 if '.' in s else 0.0
        if before:
            if before == '(':
                return 0.8 if space else 0.56
            if before == '{':
                return -0.06 if space else 0.43
            return {'[': 0.18, '=': 0.53, ':': 0.02}.get(
                before, 0.45 if '.' in before else 0.32)
        if after.startswith(','):
            return -0.14 if space else 0.26
        return {':': 0.03, ']': -0.2, '>': -0.2, '}': 0.1,
                ';': 0.1, ')': 0.31, '.': 0.62}.get(after[:1], 0.0 if space else 0.2)
    if s == "'":
        return opening_quote(previous, True) if space else 0.1 if newline else 0.2
    if len(s) >= 2 and s[1] == "'":
        return {'(': 0.51, '[': 0.14, '=': 0.31, '\\': 0.61}.get(s[0], 0.0)
    if s.startswith("'") and len(s) > 1 and not s[1:].isalnum():
        return 0.04 if newline else 0.1 if s[1] in ',:' else 0.0
    return 0.0


def context_adjustment(token, previous, gap, recent_count):
    s, p = token.strip(), previous.strip()
    word_start = float(previous[:1].isspace())
    single_letter = float(len(p) == 1 and p.isalpha())
    non_ascii = float(bool(p) and not p.isascii())
    separation = math.log1p(gap)
    if s in ('“', '‘', '「', '『'):
        return (-0.49 + 0.11 * separation + 0.27 * word_start
                + 0.13 * single_letter + 0.20 * non_ascii - 0.057 * recent_count)
    if '\\"' in s:
        return -0.13 + 0.09 * separation - 0.02 * recent_count
    if token[:1].isspace():
        return 0.0
    if s in ("'", '’'):
        return (0.28 - 0.05 * separation - 0.32 * single_letter
                + 0.22 * non_ascii - 0.034 * recent_count)
    if (s.startswith('"') and s.count('"') == 1) or s in ('”', '»', '」', '』'):
        return (-0.11 + 0.09 * separation + 0.14 * word_start
                - 0.12 * single_letter + 0.08 * non_ascii - 0.025 * recent_count)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, gap, recent = '', 64, ()
    else:
        _, previous, gap, recent = carry
    token = prefix.token_strings[-1]
    gap = min(gap + 1, 64)
    value = strength(token, previous)
    has_mark = any(c in MARKS for c in token)
    if has_mark:
        value += context_adjustment(token, previous, gap, sum(recent))
    recent = (recent + (has_mark,))[-16:]
    return (doc, token, 0 if has_mark else gap, recent), float(value)

