"""Opening quotation marks: layers.0.mlp.down_proj:5529.

What it does: the component fires on the token that opens a quotation. The strongest case is
an opening quote mark right after a word ('he said "', 'the “', 'an escaped \\" in code').
Weaker cases are quote marks that open a string in code (("  ="  ['), the possessive 's, and
the word 'some'. It stays silent on closing quotes that are glued to following punctuation
(", '." ':), on the apostrophe in contractions ('t, 're), and on ordinary text.

Why it matters: it is a token-level detector of quotation boundaries, so the model can tell
where a quoted span begins. The program predicts the activation from the current token and the
one before it, with no state across tokens."""
import re

READS = ()

QUOTE_MARKS = set('"\'“”‘’«»「」《》„『』')
CLOSING = re.compile(r'[\'"”’][,.:;)\]}!?]+\s*$')   # closing quote followed by punctuation
CODE_LEAD = ('(', '=', '[', '{')                    # code syntax directly before a quote


def activation(tok, prev):
    """The component's activation for token `tok` after token `prev`."""
    s = tok.strip()
    if s in ('some', 'Some'):
        return 0.75                                 # the quantifier 'some'
    if s in ("'s", '’s'):
        return 0.27                                 # possessive 's
    if '\\"' in tok:
        return 1.2                                  # escaped quote in code or JSON strings
    if not any(c in QUOTE_MARKS for c in tok):
        return 0.0
    if CLOSING.search(tok):
        return 0.1                                  # closing quote, e.g. '",' or '.”'
    body = tok.lstrip(' (=:[{')                     # the quote mark itself
    if body in ('」', '』', '》', '»'):
        return 0.9                                  # closing CJK or guillemet quotes
    if body == '”':
        return 1.2                                  # closing curly quote still fires
    if body in ('’', "'") and len(tok) > 1 and tok[:1] != ' ':
        return 0.0                                  # contraction apostrophe ('t, 're)
    if body in ('’', "'", '«', '「', '《', '„'):
        return 0.4 if body == '’' else 0.3
    if body in ('"', '“', '‘'):
        if prev[-1:] in QUOTE_MARKS or CLOSING.search(prev):
            return 0.1                              # right after a closing quote
        if tok[:1] in CODE_LEAD:
            return 0.55                             # a string opened in code
        if prev[-1:].isalnum() or prev[-1:] in ('.', ',', ':'):
            return 0.9                              # opens a quotation after a word
        return 0.5
    return 0.3


def step(carry, prefix, upstream):
    """Called once per token; `prefix` holds the tokens up to the current one."""
    tok = prefix.token_strings[-1]
    prev = ''
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    return None, float(activation(tok, prev))

