    'iner': -1.3, 'inet': -1.5, 'ined': -2.2, 'inem': -1.9,
    'inen': -1.55, 'inea': -1.85, 'inel': -1.8, 'ining': -1.9,
    'ina': -1.3, 'inas': -1.2, 'ino': -0.7, 'ini': -0.95,
    'mina': -1.15, 'amina': -1.0, 'mino': -0.55,
    'une': -1.1, 'una': -1.1, 'unes': -0.65,
    'atin': -0.85, 'iny': -0.8, 'inin': -0.8, 'ane': -0.3,
}


