"""Approximate a software-name ending detector.

Positive responses mark attached language, toolkit, package and class-name
endings; a standalone ordinary word is usually near zero.  Domain suffixes
also respond, especially on documentation sites.  Many two-letter web
endings, company names and print methods receive negative values.
Ordinary text receives a near-zero baseline.
Only the current whitespace-delimited fragment is retained across tokens.
"""
import re

READS = ()
LANGUAGE = set('js script cript avascript ml ql sql xml rdf net vm'.split())
PRODUCT = set('book flow fire soft ware forge studio udio engine framework'.split())
TOOLS = set('''
file library office unit forms schema binding plot viz sheet blocks code tests
'''.split())
PACKAGES = set('''
api apis sdk cli core utils tools docs parser router client server support
services widget cloud dom lib config modules resources common commons
lang runtime annotation graphics plugin plugins component io
'''.split())
BRANDS = {'Google', 'Intel', 'Microsoft', 'Apple', 'Amazon', 'Oracle'}
PROJECT_HOSTS = set('''
apache python npmjs pypi reactjs vuejs nativescript rust-lang jenkins-ci
sourceforge fhir rollupjs
'''.split())
VERSIONED_LIBRARIES = {'cv', 'opencv', 'boto', 'okhttp', 'retrofit', 'web', 'lang', 'math'}
BUILD_FILES = {'docker', 'vagrant', 'jenkins', 'gem'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fragment = carry[1] if carry and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    word = s.strip()
    body = word.lstrip('.-_/\\')
    lower = body.lower()
    attached = (not s[:1].isspace() and bool(fragment)
                and fragment[-1].isalnum())
    value = -0.003

    if attached and word == body:
        if lower in TOOLS:
            value = 0.23
        if lower in LANGUAGE:
            value = 0.41
        if lower in PRODUCT:
            value = 0.57
        if lower in PACKAGES and lower != 'io':
            value = 0.30
        if word in {'Reader', 'Search', 'Client', 'Parser', 'Writer'}:
            value = 0.22
        if lower in {'kit', 'ikit'}:
            value = 1.02
        previous = re.search(r'[a-zA-Z]+$', fragment)
        previous = previous[0].lower() if previous else ''
        if word.isdigit() and previous in VERSIONED_LIBRARIES:
            value = 0.65
        if lower == 'file' and previous in BUILD_FILES:
            value = 0.80
    if attached and lower in PACKAGES and word != body:
        value = 0.12
        if word.startswith(('.', '\\')):
            value = 0.41
        if word.startswith('-'):
            value = 0.47
            if lower in {'plugin', 'sdk', 'framework', 'runtime'}:
                value = 0.79
        if word == '.core':
            value = 1.22
    if word in {'.js', '.py', '.xml', '.sql'}:
        value = 0.11

    # Domain names: documentation/service subdomains are the strongest case.
    if word in {'.org', '.io', '.net', '.com'}:
        host = re.search(r'[a-zA-Z0-9.-]+$', fragment)
        host = host[0].lower() if host else ''
        root = host.split('.')[-1]
        value = 0.45
        if word == '.com':
            value = -0.15 if host.startswith('www.') else 0.05
            if root in {'github', 'gitlab', 'bitbucket'}:
                value = 0.17
        elif root in PROJECT_HOSTS:
            value = 0.86
        if re.search(r'(?:^|\.)(?:docs?|developers?|api|repo|registry|schemas)\.', host):
            value = 1.20
        if root in {'example', 'mydomain', 'test', 'localhost'}:
            value = -0.04
    if (word.startswith('.') and len(word) == 3 and body.isascii() and body.isalpha()
            and '://' in fragment
            and lower not in {'io', 'ai', 'js', 'ts', 'py', 'go', 'rs', 'uk'}):
        value = -0.47
    if word == '/~':
        value = -1.13
    if s[:1].isspace():
        if word == 'Studio' and fragment.endswith('Visual'):
            value = 1.55
        if word == 'Engine' and fragment.endswith(('Unreal', 'App')):
            value = 1.55
    if word in BRANDS:
        value = -0.17
    if word and len(word) >= 2 and not word.strip('_'):
        value = -0.09
    if word in {'.println', '.WriteLine'}:
        value = -0.28

    pieces = (fragment + s).split()
    fragment = pieces[-1][-160:] if pieces and not s[-1:].isspace() else ''
    return (doc, fragment), float(value)

