         'int': 0.3, 'String': 0.3, 'string': 0.2, 'static': 0.3,
         'float': 0.3, 'struct': 0.5, 'inline': 0.4, 'export': 0.5}
SMALL_SYNTAX_RESPONSES = {' `': 0.65, ' <': 0.65, '<': 0.65, ' $\\': 0.65,
    ' $$': 0.45, ' \\(': 0.45, ' {"': 0.29, '`': 0.14, '>': 0.16,
    '[]': 0.42, ' ${': 0.4, '${': 0.4, 'import': -0.16,
