    word = token.strip()
    attached = word.startswith(('(', '<'))
    if attached:
        word = word[1:]
    value = SMALL_SYNTAX_RESPONSES.get(token, 0.0)
    if word in DECLARATIONS:
        base = DECLARATIONS[word]
        readable = tail.replace('\\n', '\n').replace('\\t', '\t')
        previous = MODIFIER_END.search(readable)
        expression = 0.15 if word in {'let', 'class', 'type', 'case', 'List'} else 0.7
        if attached:
            value = expression + (0.3 if token.startswith('<') else 0.0)
        elif ((previous and previous[1] in MODIFIERS)
              or re.search(r'export\s+default\s*$', readable)):
            value = base * 1.5
            if word in {'public', 'private', 'protected', 'pub'}:
                value = base
            elif word == 'var':
