            elif word in {'fn', 'func', 'function'}:
                value = {'fn': 3.5, 'func': 4.7, 'function': 3.9}[word]
        elif LINE_START.fullmatch(tail.rsplit('\n', 1)[-1]):
            value = base
            tab_variants = {'def', 'const', 'class', 'func', 'fn', 'function'}
            if token.startswith('\t') and word in tab_variants:
                value = {'def': 1.05, 'const': 1.6, 'class': 1.25, 'func': 1.3,
                         'fn': 1.75, 'function': 1.55}[word]
            elif token.startswith(' ') and word in {'func', 'fn', 'function'}:
                value = {'func': 2.6, 'fn': 2.35, 'function': 2.1}[word]
            elif token in {'const', 'bool', 'val'}:
                value = {'const': 2.75, 'bool': 3.35, 'val': 2.8}[word]
        elif ('\\n' in tail and LINE_START.fullmatch(
                tail.rsplit('\\n', 1)[-1].replace('\\t', ''))):
            value = base * (0.7 if token[0].isspace() else 0.3)
        elif (not token[0].isspace() and tail
              and (tail[-1].isalnum() or tail[-1] == '_')):
            value = 0.0
        elif not token[0].isspace() or tail.rstrip().endswith(tuple('(,:=<{;[&')):
