    elif word in {'if', 'elif', 'try'}:
        value = 0.5 if LINE_START.fullmatch(tail.rsplit('\n', 1)[-1]) else 0.05
    elif word in {'self', 'param'}:
        same_doc = carry is not None and carry[0] == doc
        prev = prefix.token_strings[-2] if prefix.position > 0 and same_doc else ''
        if word == 'self':
            if prev.isspace():
