    elif re.fullmatch(r'<[A-Z]', token):
        value = 0.75
    elif token == ' $':
        value = -0.04 if php else (0.69 if math else 0.25)
    tail = (tail + token)[-150:]
    math = math or bool(re.search(
        r'\\(?:frac|sqrt|math|sum|in|left|right|begin)\b', tail))
    php = php or any(cue in tail for cue in ('<?php', '$this', '->'))
    return (doc, tail, math, php), value

