READS = ()
"""Declaration keywords in source code (layer-0 MLP unit 5542 of down_proj).

What it does: the unit switches on at the words that open a declaration in
program source, namely access modifiers (public, private, protected, static,
final, export, const, let, var, async), type names (void, int, long, double,
float, bool, boolean, char, byte, String) and definition keywords (func, fn,
def, function, class, struct, enum, interface, case).

How strongly, by what comes before the word:
- at the start of a line (after indentation), or right after a brace, semicolon,
  bracket or another modifier: about 2.4 (e.g. the `void` in `public void init`,
  the `func` in a Go file, the `const` in a JS block);
- after punctuation such as `(`, `,`, `=`, `:`: about 0.7 (a type in a parameter list);
- after an ordinary word, as in English prose ("the public sector", "a function
  of x"): 0.
Smaller fixed responses: a backtick (inline code) 0.4, `<` 0.6 (generics/markup),
and a capitalised type name right after a modifier (`private List<...>`) 0.5.

The predictions are a small rule set, not a learned table; they reproduce about half
of the variance. What they miss is the graded size within each class and some
scattered code tokens, which a per-token table would capture.
"""
MODIFIERS = {"public", "private", "protected", "static", "final", "export",
             "const", "let", "var", "async"}
TYPES = {"void", "int", "long", "short", "double", "float", "bool", "boolean",
         "char", "byte", "String"}
DEFINERS = {"func", "fn", "def", "function", "class", "struct", "enum",
            "interface", "case"}
KEYWORDS = MODIFIERS | TYPES | DEFINERS
CODE_MARKS = {"`": 0.4, "<": 0.6}
OPENERS = {"{", "}", ";", "]"}
PUNCT = {"(", ",", "=", ":", "[", "<", '"', "'", "`"}


def context(strings):
    """What precedes the newest token: 'line_start', 'punct' or 'word'."""
    j = len(strings) - 2
    while j >= 0 and strings[j].strip() == "" and "\n" not in strings[j]:
        j -= 1
    if j < 0 or "\n" in strings[j]:
        return "line_start"
    prev = strings[j].strip()
    if prev in OPENERS or prev in MODIFIERS:
        return "line_start"
    if prev in PUNCT or not any(c.isalnum() for c in prev):
        return "punct"
    return "word"


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    word = strings[-1].strip()
    if word in CODE_MARKS:
        return None, CODE_MARKS[word]
    if word not in KEYWORDS:
        if word[:1].isupper() and len(strings) > 1 and strings[-2].strip() in MODIFIERS:
            return None, 0.5
        return None, 0.0
    ctx = context(strings)
    if ctx == "line_start":
        return None, 2.4
    if ctx == "punct":
        return None, 0.7
    return None, 0.0

