programs.sol:
"""Approximate lexical unfamiliarity using token rarity, length, case and script.

For merged ordinary Qwen tokens, token id minus 256 is the byte-pair merge
rank. Initial byte tokens get the minimum rank. Later merging is a rough
familiarity proxy, not a literal word-frequency measurement. Longer words
naturally need later merges, so adjust their rank downward before predicting
a logarithmic rarity response. Leading spaces stand in for word beginnings;
capitalization and writing systems receive different curves.

Chat/tool/thought delimiters have separate responses. At a row/document's
first ordinary token, use 60% of the estimate plus 0.04. No lexical lookup is
used: individual words can deviate substantially from these broad rules.

Merge ordering verified against the official tokenizer:
https://huggingface.co/Qwen/Qwen3-1.7B/resolve/main/tokenizer.json
"""

from math import log

READS = ()

DELIMITERS = {
    '<|endoftext|>': 0.01,
    '<|im_end|>': 1.99,
    '<tool_call>': 0.20,
    '</tool_call>': 3.70,
    '<tool_response>': -0.57,
    '</tool_response>': 1.72,
    '<think>': 0.18,
    '</think>': 1.63,
}


def rarity(rank, threshold, gain, baseline=0.0, length_penalty=0.0):
    unusualness = max(0.0, log(rank / threshold) - length_penalty)
    return baseline + gain * unusualness


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry != doc
    s = prefix.token_strings[-1]
    t = s.strip()
    rank = max(1, int(prefix.token_ids[-1]) - 256)
    beginning = s.startswith(' ')
    extra_length = max(0, len(t) - 4)

    if s == '<|im_start|>':
        value = 0.36 if first else 2.17
    elif s in DELIMITERS:
        value = DELIMITERS[s]
        if first and s == '<|im_end|>':
            value = 1.40
        elif first and s == '</tool_call>':
            value = 1.71
    elif not t:
        value = rarity(rank, 36000, 0.05, 0.01)
    elif '\ufffd' in s:
        value = rarity(rank, 9000, 0.36, 0.28)
    elif not any(c.isalpha() for c in t):
        value = rarity(rank, 34000, 0.11)
    elif any('\u4e00' <= c <= '\u9fff' for c in t):
        value = rarity(rank, 33000, 0.32, 0.04)
    elif any('\u0400' <= c <= '\u04ff' for c in t):
        if beginning:
            value = rarity(rank, 33000, 0.45, length_penalty=0.10 * extra_length)
        else:
            value = rarity(rank, 23000, 0.07, -0.05)
    elif any('\uac00' <= c <= '\ud7af' for c in t):
        value = rarity(rank, 17500, 0.19, -0.08)
    elif not t.isascii():
        if beginning:
            value = rarity(rank, 16000, 0.27, 0.04)
        else:
            value = rarity(rank, 20000, 0.19, -0.07)
    elif not t.isalpha():
        value = rarity(rank, 4500, 0.07, -0.03)
    elif len(t) == 1:
        value = -0.03
    elif not beginning:
        value = rarity(rank, 10000, 0.11, length_penalty=0.14 * extra_length)
    elif t.istitle():
        value = rarity(rank, 9000, 0.55, 0.01, 0.22 * extra_length)
    elif t.isupper():
        value = rarity(rank, 15000, 0.40, 0.06, 1.00 * extra_length)
    elif t.islower():
        value = rarity(rank, 2700, 0.23, length_penalty=0.28 * extra_length)
    else:
        value = rarity(rank, 7000, 0.26, 0.07)
    if first and s not in DELIMITERS and s != '<|im_start|>':
        value = 0.04 + 0.60 * value
    return doc, float(value)

