"""Layer-0 MLP down-projection unit 5544: a negative "with" detector.

The unit reads the word "with" (and sentence-initial "With") and writes a
negative value into the residual stream. How negative depends on the word
just before it:
- after a verb/adjective of working or engaging with someone or something
  ("work with", "deal with", "help with", "familiar with", "done with",
  "you with"): strongly negative (about -2.2);
- after a comma, or at the start of a document: weakly negative (about -0.3);
- after a comparison, connection or passive participle ("compared with",
  "connected with", "matches with", "filled with", "replaced with"): about 0;
- any other "with": moderately negative (about -0.65);
- "with" in other languages that carry the same meaning ("с" Russian, "con"
  Spanish/Italian, "avec" French): weakly negative (about -0.3).
Every other token predicts 0.
"""
READS = ()

WITH = {"with", "With"}
FOREIGN = {"с", "con", "avec"}
ENGAGE = {"help", "working", "work", "worked", "do", "deal", "dealing", "familiar",
          "issues", "problem", "problems", "proceed", "start", "starting", "begin",
          "done", "you", "satisfaction", "interfere", "go", "living", "finished",
          "associated", "interact", "completed", "me", "comply", "compliance"}
NEUTRAL = {"compared", "connected", "match", "matches", "called", "link", "connection",
           "agreement", "mixed", "line", "each", "measured", "together", "replaced",
           "treated", "correlated", "comparison", "triangle", "accordance", "filled",
           "covered", "loaded", "equipped", "adorned", "obtained", "met", "along"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip()
    if cur in FOREIGN:
        return carry, -0.3
    if cur not in WITH:
        return carry, 0.0
    if len(toks) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -0.3
    prev = toks[-2].strip()
    if prev in ENGAGE:
        return carry, -2.2
    if prev in NEUTRAL:
        return carry, 0.0
    if prev == ",":
        return carry, -0.3
    return carry, -0.65

