"""Approximate a formatting-and-script response, not general word meanings.

Bare hyphens and other list/table markers are strongly negative after a
newline, weaker after other whitespace. Numbers after a newline get a negative offset.
Digits near Han, kana or Hangul are positive; this fades as characters intervene.
Calendar units and the ordinal prefix 第 strengthen that numeric response.
Fused, escaped and indented markers are weaker; a preceding mathematical line
also weakens a hyphen. Most other tokens receive a near-zero prediction.

State contains only the previous token, script recency and a short text tail;
it resets at document boundaries. Coefficients were fitted on training rows.
"""
READS = ()
MARKERS = {'-': -1.8, '*': -0.65, '•': -0.34, '·': -0.83,
           '|': -0.55, '_': -0.45, '+': -0.24,
           '–': -0.82, '—': -0.6, '・': -0.51}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 1000, 0.0, '')
    _, previous, distance, strength, recent = carry
    s = prefix.token_strings[-1]
    value = -0.004
    numeric = bool(s) and s.isdecimal()
    if numeric:
        # Combine script proximity with number-label formatting.
        fade = ((1 + max(0, distance - 1) / 3) ** -0.8
                if distance < 150 else 0.0)
        newline = previous.endswith('\n')
        tail = previous.rstrip()
        level = strength
        if previous.isdecimal():
            level += 0.14
        if newline:
            level -= 0.10
        elif previous.isspace():
            level -= 0.05
        value = level * fade
        if newline:
            value -= 0.16 + 0.05 * (previous.count('\n') > 1)
            if tail.endswith(('.', '!', '?')):
                value -= 0.12
            elif tail.endswith(':'):
                value -= 0.18
        if previous.endswith(('(', '[', '{', '/')):
            value += 0.04
        if previous in ('年', '月', '日'):
            value += 0.10
        elif previous == '第':
            value += 0.35
        if '０' <= s[0] <= '９':
            value += 0.03
    else:
        # Recognize marker shapes, rather than a table of token identities.
        trim = s.strip()
        escaped = trim.startswith('\\-')
        if escaped:
            trim = trim[1:]
        marker = trim[:1]
        is_marker = (marker in MARKERS and
                     (trim == marker or
                      (marker == '-' and trim[1:].isalpha())))
        if is_marker:
            scale = 0.5 if escaped else 1.0
            if trim != marker:
                scale *= 0.67
            if s[:1].isspace():
                scale *= 0.2
            if '\n' in s:
                scale *= 0.25
            if previous.endswith('\n'):
                value = MARKERS[marker]
                tail = previous.rstrip()
                if marker == '-':
                    if tail.endswith(('.', ':', '!')):
                        value -= 0.12
                    elif tail and tail[-1] in '{}();,':
                        value += 0.33
                    elif tail.endswith('。'):
                        value += 0.44
                    if previous.count('\n') > 1:
                        value += 0.21
                    last_line = recent.rstrip().rsplit('\n', 1)[-1]
                    if ('=' in last_line and
                            sum(c.isdecimal() for c in last_line) > 1):
                        value += 0.32
                elif tail.endswith(('.', ':', '!')):
                    value -= 0.1
                value *= scale
            elif not previous and trim == marker:
                value = MARKERS[marker] * 0.5 * scale
            elif previous.isspace() or recent.endswith('\\n'):
                value = MARKERS[marker] * 0.43 * scale
            elif marker == '-':
                value = -0.015
                if distance < 30:
                    value += 0.3 / (1 + distance / 5)
            elif marker == '*':
                value = -0.05
            elif marker == '_':
                value = 0.03
            elif marker in ('·', '・', '—') and distance < 20:
                value = (0.6 if marker == '—' else 0.4) / (1 + distance / 8)
    # Remember the most recent East Asian character and its script.
    for c in s:
        if '\u3400' <= c <= '\u9fff':
            distance, strength = 0, 0.61
        elif '\u3040' <= c <= '\u309f':
            distance, strength = 0, 0.44
        elif '\u30a0' <= c <= '\u30ff':
            distance, strength = 0, 0.28
        elif '\uac00' <= c <= '\ud7af':
            distance, strength = 0, 0.26
        else:
            distance += 1
    return (doc, s, distance, strength, (recent + s)[-160:]), float(value)

