"""Recognize Asian-text numerals and plain-text list markers.

The conspicuous positive responses in the examples are digits embedded in
Chinese, Japanese, or Korean text. The large negative responses are mostly
hyphen bullets; smaller negative responses mark Western numbered list items.
This uses only nearby text and deliberately ignores other MLP activity.
"""

READS = ()


def _asian_letter(ch):
    n = ord(ch)
    return (
        0x3400 <= n <= 0x9FFF
        or 0xF900 <= n <= 0xFAFF
        or 0x3040 <= n <= 0x30FF
        or 0xAC00 <= n <= 0xD7AF
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = ""
    else:
        previous = carry[1]

    current = prefix.token_strings[-1]
    nearby = previous[-24:]
    has_asian = any(_asian_letter(ch) for ch in nearby)
    is_digit = any(ch.isdigit() for ch in current)

    if is_digit and has_asian:
        value = 0.65
    else:
        line_prefix = previous.rsplit("\n", 1)[-1].strip()
        stripped = current.strip()
        if not line_prefix and stripped.startswith(("-", "–", "—")):
            value = -1.5
        elif not line_prefix and stripped and stripped[0] in "•*▪‣":
            value = -0.4
        elif not line_prefix and is_digit:
            value = -0.45
        elif stripped.startswith(("|",)):
            value = -0.35
        elif not line_prefix and stripped.startswith("_"):
            value = -0.34
        else:
            value = 0.0

    joined = (previous + current)[-96:]
    # The text cues are useful but sparse and imperfect; shrink them toward the
    # component's small negative corpus-wide baseline.
    return (doc, joined), float(0.4 * value - 0.00446)

