    ({'”', '»', '」'}, 0.44),              # closing quotations
    ({'**'}, 0.37),                        # emphasis
    ({' :', '：'}, 0.45),                 # text introducers
    ({' }'}, 0.47),                        # spaced block closer
    ({'}}', '{}', '[]'}, 0.33),            # paired brackets
    ({'...', '....', '…', '--'}, 0.38),   # omissions or long dashes
