"""Lexical detector of unspecified things, alternatives, and dummy names.

Give a positive activation to English 'some/other' words and conventional
placeholders. Chinese 某 ('a certain', also anonymizing a person's name)
gets a stronger response. Other tokens receive zero. This captures the main
positive lexical response, not the component's small background variations.
"""
READS = ()

INDEFINITE = {
    'some', 'something', 'someone', 'somebody', 'somewhere',
    'somehow', 'someday', 'other', 'another', 'hypothetical',
}
CHINESE = {
    '某': 5.75, '某某': 5.2, '某个': 3.8, '某一': 3.5,
    '某种': 2.7, '某些': 1.8,
    '该': 1.05, '該': 1.05, '另一': 1.3, '另': 0.95,
    '另外': 0.62,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip('([_./@\'"-')
    word = spelling.lower()
    if word in INDEFINITE:
        if token == 'Some':
            return None, 1.43
        return None, 1.13
    if word in {'others', 'particular', 'somewhat', 'abc'}:
        return None, 0.36
    if word in {'certain', 'elsewhere', 'sometime', 'unnamed'}:
        return None, 0.6
    if word in {'foo', 'xyz'} or spelling in {'TODO', 'FIXME', 'Doe'}:
        return None, 1.1
    if len(word) >= 2 and set(word) == {'x'}:
        return None, 1.0 if token[0].isspace() else 1.4
    if word in CHINESE:
        return None, CHINESE[word]
    if len(word) == 2 and word.endswith('某'):
        return None, 3.7  # An anonymized surname.
    if word.endswith(('其他', '其它', '另一个')):
        return None, 1.05
    if word.endswith(('一些', '有些')):
        return None, 0.65
    return None, 0.0

