"""A graded English perfect-tense heuristic: HAVE plus a past participle.

It responds most to participles just after have/has/had/having. Contractions
and intervening adverbs weaken the response. BEEN and a few very common
irregular participles have their own fitted strengths. Nonverbal HAVE
complements get a small negative value; most other tokens get zero.
"""
READS = ()
# Auxiliary: participle multiplier, BEEN response.
AUX = {
    'have': (1.0, 3.7), 'has': (1.15, 4.4), 'had': (.86, 3.5),
    'having': (1.07, 4.2), "'ve": (.84, 3.9), "'s": (.2, 2.5),
    "'d": (.55, 2.6),
}
IRREGULAR = set('''arisen beaten become begun bent bitten blown born borne
bought brought broken built caught chosen come cost cut dealt done drawn
driven drunk dug eaten fallen fed felt fought flown forgotten forgiven
found frozen given gone got gotten grown had heard held hidden hit hurt
kept known laid led left lent let lost made meant met paid put read ridden
risen run said sat seen sent set shaken shed shone shot shown shrunk shut
slain slept sold sought spoken spent split spread stood stolen struck stuck
sung sunk swept swum taken taught thought thrown told torn undergone
understood withdrawn woken worn won woven written proven learnt fled'''.split())
INVARIANT = {'cut', 'cost', 'hit', 'hurt', 'let', 'put', 'read', 'run', 'set'}
STRENGTH = {
    'done': 6.0, 'gone': 5.8, 'taken': 5.6, 'heard': 5.6,
    'fallen': 5.5, 'won': 5.4, 'left': 2.1, 'known': 2.5,
    'got': 1.2, 'limited': 1.3, 'unintended': .2,
}
ADVERBS = {
    'always': 3., 'never': 2.7, 'ever': 2.3, 'successfully': 3.5,
    'just': 2.3, 'previously': 2.3, 'fully': 2.3,
    'recently': 1.8, 'long': 1.8, 'already': 1.3, 'also': 1.2,
    'not': .7, 'even': .3, 'all': .3, 'both': -.3,
    'only': 0., 'now': 0., 'still': 0., 'yet': 1.2, 'often': 1.,
}
PRONOUNS = {'i', 'you', 'he', 'she', 'it', 'we', 'they'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, previous, aux, age = carry
    word = prefix.token_strings[-1].strip().lower().replace('’', "'")
    regular = (word.isalpha() and word.endswith('ed') and
               word not in {'hundred', 'speed'} and
               (len(word) > 4 or word in {'used', 'died', 'tied', 'owed'}))
    participle = regular or word in IRREGULAR
    adverb = word in ADVERBS or (word.isalpha() and word.endswith('ly'))
    value = 1.4 if word == 'been' else .02 if participle else 0.0
    if aux:
        scale, been = AUX[aux]
        if word == 'been':
            value = been * .8 ** (age - 1)
        elif participle:
            base = 3.7 if regular or word in INVARIANT else 4.3
            value = STRENGTH.get(word, base) * scale * .6 ** (age - 1)
        elif adverb:
            scale = min(1., scale)  # HAS does not amplify adverbs.
            value = ADVERBS.get(word, 1.) * scale * .6 ** (age - 1)
        else:
            value = -.4 * scale if age == 1 and word.isalpha() else 0.0
            if aux == "'s":
                value = 0.0
    if word in AUX:
        aux, age = word, 1
    elif word in {'haven', 'hasn', 'hadn'}:
        aux, age = word[:-1], 1
    elif word == "'t" and previous in {'haven', 'hasn', 'hadn'}:
        age = 2
    elif aux and age < 3 and (adverb or word in PRONOUNS or not word):
        age += 1
    else:
        aux, age = '', 0
    return (doc, word, aux, age), float(value)

