"""Present-perfect participle detector for layers.0.mlp.down_proj:5551.

The component fires on the past participle of a perfect construction: the word
right after has/have/had (or having, 've, haven't, hasn't, hadn't), with up to two
adverbs or "not" in between, as in "has [been]", "have [seen]", "had [gone]",
"has long [been]", "haven't [tried]". Strongest on "been" (~4), other participles
about 3.5. Passive "is/was/be + participle" does not fire. Adverbs in that
position get a weak value (~1.5), and "been" after "it's"/"there's" gets 2.5.
Everything else predicts 0.
"""

READS = ()

AUX = {"have", "has", "had", "having", "ve", "haven", "hasn", "hadn"}
ADVERBS = {"never", "ever", "also", "already", "not", "t", "just", "always", "recently", "still", "yet", "only", "long", "often", "previously", "now", "really", "probably", "obviously", "quite", "even", "all", "both", "finally", "well"}
IRREGULAR = {"been", "come", "become", "had", "made", "done", "gone", "heard", "held", "kept", "lost", "led", "left", "met", "paid", "run", "said", "sent", "shown", "spent", "told", "won", "taken", "found", "felt", "brought", "bought", "caught", "taught", "fed", "sold", "built", "meant", "hit", "put", "read", "cut", "set", "let", "hurt", "thought", "fought", "sought", "struck", "drawn", "thrown", "grown", "known", "begun", "broken", "chosen", "spoken", "stood", "forgotten", "driven", "risen", "written"}


def _word(token):
    return token.strip().lower().replace("’", "'").strip("'")


def _is_adverb(word):
    return word in ADVERBS or (len(word) > 4 and word.endswith("ly"))


def _is_participle(word):
    return word in IRREGULAR or (len(word) > 3 and word.endswith(("ed", "en")))


def _after_aux(words):
    """True if the last word follows have/has/had, with up to two adverbs or 'not' between."""
    for back, word in enumerate(reversed(words[:-1])):
        if word in AUX:
            return True
        if not _is_adverb(word) or back >= 2:
            return False
    return False


def step(carry, prefix, upstream):
    words = [_word(s) for s in prefix.token_strings[-4:]]
    word = words[-1]
    before = words[-2] if len(words) > 1 else ""
    if word == "been" and before == "s":
        return None, 2.5  # "it's been", "there's been"
    if not _after_aux(words):
        return None, 0.0
    if _is_adverb(word):
        return None, 1.5
    if _is_participle(word):
        return None, 4.0 if word == "been" else 3.5
    return None, 0.0

