"""Approximate a sparse English past/perfect-verb feature from the current word.
A completed -ed form or common irregular participle gets a modest response; a
past-participle cue near have/be/get makes the response stronger.  The cue is
not a general tense tag, so this misses unlisted irregulars and other contexts."""
import re

READS = ()

IRREGULAR_PARTICIPLES = {
    "been", "become", "begun", "bitten", "blown", "broken", "brought",
    "built", "bought", "caught", "chosen", "come", "cut", "dealt",
    "done", "drawn", "driven", "eaten", "fallen", "felt", "found",
    "flown", "forgotten", "forgiven", "frozen", "given", "gone", "grown",
    "heard", "held", "hidden", "hit", "kept", "known", "led", "left",
    "lost", "made", "meant", "met", "paid", "put", "read", "run",
    "said", "seen", "sold", "sent", "set", "shown", "shut", "sung",
    "sat", "slept", "spent", "spoken", "stood", "stolen", "stuck",
    "swept", "taken", "taught", "thought", "thrown", "understood",
    "worn", "written", "proven", "gotten", "got", "led", "laid", "lost",
}
AUXILIARIES = {
    "have", "has", "had", "having", "be", "been", "being", "is", "are",
    "am", "was", "were", "get", "gets", "got", "getting", "'ve", "'s",
    "'d", "’ve", "’s", "’d",
}
ADVERBS_BEFORE_PARTICIPLE = {
    "always", "also", "already", "ever", "never", "often", "just", "yet",
    "long", "recently", "previously", "finally", "still",
}
WORD = re.compile(r"[A-Za-z]+(?:['’][A-Za-z]+)?")


def is_auxiliary(word):
    return (
        word in AUXILIARIES
        or word.endswith(("'ve", "’ve", "'d", "’d"))
        or word in {
            "i's", "it's", "he's", "she's", "that's", "there's", "here's",
            "what's", "who's", "where's", "when's", "why's", "how's",
            "which's", "whoever's", "who's", "it’s", "he’s", "she’s",
            "that’s", "there’s", "here’s", "what’s", "who’s", "where’s",
            "when’s", "why’s", "how’s", "which’s",
        }
        or word in {"haven't", "hasn't", "hadn't", "haven’t", "hasn’t", "hadn’t"}
    )


