    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = ""
    else:
        history = carry[1]
    text = (history + token)[-160:]
    words = WORD.findall(text.lower())
    if not words:
        return (doc, text), 0.0
    current = words[-1]
    previous = words[-7:-1]
    auxiliary_distance = next(
        (len(previous) - i for i in range(len(previous) - 1, -1, -1)
         if is_auxiliary(previous[i])),
        99,
    )
    participle = current in IRREGULAR_PARTICIPLES or (
        len(current) > 4 and current.endswith("ed")
    )
    adverbial_slot = (
        current in ADVERBS_BEFORE_PARTICIPLE
        and auxiliary_distance <= 3
    )
    helper = previous[-auxiliary_distance] if auxiliary_distance < 99 else ""
    if participle and auxiliary_distance <= 5:
        if helper in {"get", "gets", "got", "getting"}:
            value = 1.0
        elif (
            helper in {"have", "has", "had", "having", "haven't", "hasn't", "hadn't"}
            or helper.endswith(("'ve", "’ve", "'d", "’d"))
        ):
            value = 3.8 if auxiliary_distance <= 2 else 2.4
        else:
            value = 1.3
    elif adverbial_slot:
        value = 1.8
    elif participle:
        value = 0.5
    else:
        value = 0.0
    return (doc, text), float(0.45 * value)

