                value = 1.36 if previous.strip() else 1.21
            elif len(line) == 1:
                value = 0.51
            elif len(line) <= 3:
                value = 0.71
            elif len(line) == 4:
                value = 0.66
            else:
                value = 0.28
        elif previous.isspace():
            value = 0.16 if len(previous) == 1 else 0.32
        elif line.strip() in COMMENT_MARKERS:
            value = 0.55 if '/' in line else 0.35
        else:
            value = -0.003
    elif token == '  ':
