READS = ()

SUB_MARK = re.compile(r"^[)}]?_[{\\]?$")         # _  _{  }_{  _\  )_
SUP_DIGITS = {"²": 0.9, "³": 0.6, "¹": 0.1}
SUB_DIGITS = {"₁": 0.9, "₂": 0.8}
LATEX_PUNCT = {"\\", " \\", "{\\", "(", "{", "}", "/", "(\\", "}\\", "}}", "}{"}


def in_maths(strings):
    """True if the recent text has a LaTeX command or a dollar sign."""
    return any("\\" in s or "$" in s for s in strings[-30:])


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    maths = in_maths(prefix.token_strings)
    if "^" in s:
        # an exponent after a variable, digit or closing bracket; not after '[' as in regexes
        if before[-1:] == ")":
            return carry, 1.5
        return carry, 3.0 if before[-1:].isalnum() or before[-1:] == "}" else 0.5
    if SUB_MARK.match(s) and maths:
        return carry, 2.5
    if s in SUP_DIGITS:
        return carry, SUP_DIGITS[s]
    if s in SUB_DIGITS:
        return carry, SUB_DIGITS[s]
    if maths and s in LATEX_PUNCT:
        return carry, 0.6 if s == "{\\" else 0.4
    return carry, 0.0

programs.luna:
"""Approximate the response to math and formula-style notation.

Exponent and subscript marks are strongest cues; LaTeX-like controls,
grouping marks, and Unicode super/subscripts are weaker cues. The output
stays close to baseline because a cue raises the response without fixing it.
"""
READS = ()
BASE = 0.01
SCALE = 0.26
SUPER_AND_SUBSCRIPTS = frozenset(
    '⁰¹²³⁴⁵⁶⁷⁸⁹₀₁₂₃₄₅₆₇₈₉⁺⁻⁼⁽⁾₊₋₌₍₎'
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    symbol = token
    if '\ufffd' in token:
        text = prefix.text_prefixes[-1]
        if text:
            symbol = text[-1]

    previous = prefix.token_strings[-2] if len(prefix) > 1 else ''

    if '^(' in token:
        raw = 1.65
    elif '}_' in token or '_{' in token:
        raw = 3.3
    elif '^' in token:
        raw = 2.65
    elif '_' in token:
        raw = 1.7
    elif '\\' in token:
        raw = 1.0
    elif token == '{' and '\\' in previous:
        raw = 0.9
    elif token in ('(', ' ('):
        raw = 0.65
    elif token == ')':
        raw = 0.28
    elif token in ('{', '}'):
        raw = 0.8
    elif any(ch in symbol for ch in SUPER_AND_SUBSCRIPTS):
        raw = 0.8
    else:
        raw = BASE

    return None, BASE + SCALE * (raw - BASE)

"""Approximate signed responses to short French function words.

The component is quiet at most positions. It often responds strongly and
negatively to "de" and its contractions, and positively to "le" and "ce",
when nearby words look French. It also responds to "plus" and accented "à".
The trailing-word test is a short, readable cue for context, not a
reconstruction of the model's attention.
"""

READS = ()

FRENCH_LINK_WORDS = {"de", "des", "du", "d"}
FRENCH_CUES = {
    "à", "au", "aux", "avec", "ce", "ces", "dans", "des", "du",
    "en", "et", "est", "la", "le", "les", "ne", "pas", "par",
    "pour", "que", "qui", "sur", "un", "une",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    has_french_cue = any(previous in FRENCH_CUES for previous in history)

    if word == "plus":
        value = -2.2 if has_french_cue else -0.8
    elif word in FRENCH_LINK_WORDS and has_french_cue:
        value = -1.25
    elif word in {"le", "ce"} and has_french_cue:
        value = 1.1
    elif word == "l" and has_french_cue:
        value = 0.5
    elif word == "à":
        value = -0.25
    else:
        value = 0.0

    return (doc, (history + (word,))[-16:]), value

programs.sol:
"""Approximate a negative EN-spelling response in short word fragments.

EN before vowels or doubled N, PEN/BEN, and the keyword ENUM are strong.
ENT/END and selected familiar words are weak. Accents are folded, and
initial Cyrillic ЕН has related rules. Decaying German/English function-word
counts soften some endings and make several German inflections positive.
State resets between documents. Finer token-specific strengths and unrelated
lexical responses are deliberately omitted to keep a spelling explanation.
"""
import unicodedata
from functools import lru_cache

READS = ()
GERMAN = set('der die das den dem des ein eine und ist sind nicht sich '
             'mit von zu auf auch im am aus bei nach wir sie werden'.split())
ENGLISH = set('the a an of with from and to is are was were that this '
              'not it he she they for'.split())
WEAK = set('when then been even open wenn sense scent een bien haven'.split())


@lru_cache(maxsize=8192)
def spelling_value(token):
    raw = token.strip().strip('._/-:(\'"')
    word = ''.join(c for c in unicodedata.normalize('NFD', raw.lower())
                   if not unicodedata.combining(c))
    spaced = token[:1].isspace()
    if word.startswith('ен'):
        tail = word[2:]
        if tail.startswith(('д', 'т')):
            return -0.05
        if tail.startswith(('и', 'н')):
            if len(tail) == 1:
                return -2.1
            return -0.35 if tail[0] == 'и' else -1.1
        return -1.2
    j = word.find('en')
    if j < 0 or word in WEAK:
        return 0.0
    if word.startswith('enum'):
        return -3.6 if word == 'enum' else -1.7
    if word.startswith(('general', 'generat', 'enabl', 'enough', 'enjoy',
                        'eness', 'eneral', 'enerat', 'genuin', 'opening')):
        return 0.0
    tail = word[j + 2:]
    if tail[:1] in ('d', 't'):
        return -0.05
    if j == 0:
        if not tail:
            if spaced:
                return -0.5 if raw[:1].isupper() else -0.15
            return -1.0
        if spaced:
            return -0.25
        if tail[0] in 'aeioun':
            if tail.endswith('en'):
                return -0.8
            if len(word) == 3:
                return -2.7 if tail[0] in 'aon' else -2.0
            return -1.5
        return -0.7
    if j == 1:
        if not tail and word[0] in 'lnzi':
            return 0.1 if word[0] == 'n' else -0.25
        if spaced and word == 'den':
            return -0.25
        if word[0] in 'bp':
            if not tail:
                return -2.5 if spaced or raw[:1].isupper() else -1.3
            return -0.7 if tail.startswith('ef') else -1.3
        if tail[:1] == 'g':
            return -0.05
        return -0.6 if len(word) <= 7 else -0.25
    if word.startswith(('phen', 'scen')):
        return -1.6 if len(word) <= 5 else -0.9
    if 'enu' in word or word.endswith(('ien', 'aven')):
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        german, english, word = 0.0, 0.0, ''
    else:
        _, german, english, word = carry
    previous_word = word
    german, english = 0.92 * german, 0.92 * english
    if token[:1].isspace():
        german += word.lower() in GERMAN
        english += word.lower() in ENGLISH
        word = token.strip()
    else:
        word = (word + token)[-60:]
    is_german = german > english + 0.25
    value = spelling_value(token)
    if token == 'en':
        value = -0.5 if is_german else -1.3
        if previous_word[-1:].isupper() or previous_word.endswith('://'):
            value = -2.0
    if is_german and token in ('ben', 'ene', 'hen'):
        value += 0.5
    if token in ('igen', 'ten', 'ungen', 'enden', 'lichen'):
        value = 0.25 if is_german else -0.2
    return (doc, german, english, word), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:5559: a detector for the spelling "en" in short tokens.

The component goes negative on the current token when its text contains "en" (or the
Cyrillic "ен"), and the size depends on how much of the token the "en" makes up:

- a short fragment (up to 3 letters) that opens with "en" before a vowel or "n"
  ("ene", "enn", "ena", "ens") is strongest;
- "en" opening a short token before a consonant, or a token that is just "en", is medium;
- "en" in the middle of a token before a vowel ("Menu", "Benz") is medium;
- a short token ending in "en" ("ben", "men", "hen") is weaker;
- long words that merely contain "en" ("engine", "comment", "density") are weak, and
  "en" inside a consonant cluster ("ment", "ence") is zero.

Everything else predicts 0. It reads only the current token's text.
"""

VOWELS = set("aeiouyáéíóúàèìòùäöüâêîôûæøå")


def activation(token):
    t = token.strip().lower()
    short = len(t) <= 3
    if "ен" in t:
        return -0.9 if short else -0.3
    i = t.find("en")
    if i < 0:
        return 0.0
    after = t[i + 2] if i + 2 < len(t) else ""
    if i == 0:
        if after in VOWELS or after == "n":
            return -2.2 if short else -0.65
        if after == "":
            return -0.6
        return -0.3 if short else -0.18
    if after in VOWELS:
        return -0.4
    if after == "":
        return -0.6 if short else -0.04
    return 0.0


READS = ()


def step(carry, prefix, upstream):
    return carry, float(activation(prefix.token_strings[-1]))

"""Draft 2: tiered strengths by word and context."""
READS = ()

PREPOSITIONS = {"of", "in", "on", "for", "at", "from", "with", "to", "by", "about", "through", "during",
                "under", "into", "after", "between", "than", "over", "without", "against"}
# Demonstrative / object pronouns and how strongly they go negative after a preposition.
PREP_STRENGTH = {"this": 3.3, "that": 4.0, "it": 4.4, "them": 3.2,
                 "these": 1.9, "those": 1.3, "him": 2.2, "us": 2.1, "me": 1.6, "you": 1.6,
                 "which": 1.4, "such": 1.9, "whom": 1.1, "her": 0.8}
# After other words (verbs, nouns), only the demonstratives and object pronouns still respond.
OTHER_STRENGTH = {"this": 1.0, "them": 1.0, "it": 0.6, "him": 0.7, "these": 0.7, "such": 0.3}


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.0
    raw = prefix.token_strings[-1]
    word = raw.strip()
    if not raw.startswith(" ") and word != "this":
        return None, 0.0
    prev = prefix.token_strings[-2].strip()
    if prev in PREPOSITIONS:
        return None, -PREP_STRENGTH.get(word, 0.0)
    if prev in {",", ".", "and", "but", "or", "so", "if", "as", "when", "is", "that", "where", "because",
                "since", "then", ";", ":", "=", "(", '"', "'", ""}:
        return None, 0.0
    return None, -OTHER_STRENGTH.get(word, 0.0)

programs.luna:
"""Approximate the component with weak negative scores for reference words.

The harvested large responses often occur on words like "this", "that", and
"it". This rule captures that lexical cluster; it does not identify which
references are especially important in context.
"""

READS = ()

DEMONSTRATIVES = {
    "this", "that", "these", "those", "questa", "questo", "这个", "如此",
}
PRONOUNS = {
    "it", "they", "them", "their", "its", "he", "him", "his",
    "she", "her", "hers", "we", "us", "our", "you", "me",
}
OTHER_REFERENTS = {"which", "who", "what", "here", "there"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip("\"'“”‘’([{<,.;:!?)]}>")
    if word in DEMONSTRATIVES:
        value = -0.60
    elif word in PRONOUNS:
        value = -0.35
    elif word in OTHER_REFERENTS:
        value = -0.20
    else:
        value = -0.009
    return None, value

programs.sol:
"""A tr-spelling detector, with a weaker dr response.

Short fragments ending in tr fire most strongly; letters after the cluster
weaken it. Latin prefixes, case, and spacing modify the strength. A final
t/d followed by a continuation beginning r also counts, but CamelCase does
not. Cyrillic/Greek dental stops and r, and Czech ř, are treated similarly.
Conversation delimiters and 'another' are separate lexical responses.
"""
READS = ()
TRANSLITERATE = str.maketrans({'т': 't', 'р': 'r', 'д': 'd', 'с': 's',
                             'τ': 't', 'ρ': 'r', 'δ': 'd', 'ř': 'r'})
MARKERS = {'<|im_start|>': 1.1, '<think>': 0.97, '</think>': 1.83,
           '<tool_response>': 0.94, '</tool_response>': 1.58}


def spelling(text):
    return text.lower().translate(TRANSLITERATE)


def response(token, previous):
    if token in MARKERS:
        return MARKERS[token]
    word = spelling(token).strip()
    if word == 'another':
        return 1.14 if token.strip().islower() else 1.39
    j = word.find('tr')
    if j >= 0:
        before, after = word[:j], word[j+2:]
        n = len(after)
        base = (3.14 if n == 0 else 2.75 if n == 1 and after in 'aio'
                else 1.5 if n == 1 else 0.85 if n == 2
                else 0.75 if n <= 6 else 0.6)
        value = base / (1 + 0.1 * len(before))
        if token.startswith(' ') and n <= 1:
            value -= 0.23 if n == 0 else 0.45
        if before.endswith('s'):
            value -= 0.4 / (n + 1)
        # Intra-/extra-, contra-/entry-, at-, and re- fragments.
        boost = (2.0 if before in ('in', 'ex') else 1.1
                 if before in ('con', 'en', 'a', 'at') else 0.4
                 if before == 're' else 0.0)
        value += boost / (n + 1)
        if after.startswith(('ue', 'ee')):
            value -= 0.4
        cluster = token.strip()[j:j+2]
        if n == 0:
            value += 0.3 if cluster.isupper() else -0.4 if cluster[0].isupper() else 0
        return max(0.0, value)
    if word.startswith('r') and not token[0].isspace():
        p = spelling(previous)
        camel = token[0].isupper() and previous[-1:].islower()
        if not camel and p.endswith(('t', 'd')):
            strength = 1.6 if p.endswith('t') else 0.85
            return strength / (1 + 0.18 * (len(word)-1)**1.7)
    if 'dr' in word:
        return 0.8 / (1 + 0.2 * max(0, len(word)-2))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, previous)
    if token == '<|im_start|>' and not previous:
        value = 0.30
    return (doc, token), float(value)

"""Approximate a response to isolated u-like letters and vowel-sized marks.

Unicode vowel-sign U and Thai sara u get large positive values. Smaller
values mark common Greek vowels, Latin u (especially ü), Cyrillic у, Arabic
vowel marks, and small kana. Longer word tokens normally receive zero.
Greek ου and upsilon after omicron/epsilon get a diphthong response. State
tracks the document and preceding completed character, including split UTF-8.
"""
import unicodedata as ud

READS = ()
GREEK_VOWELS = {
    'ε': 0.8, 'έ': 1.1, 'Ε': 1.25, 'ι': 0.64, 'ί': 0.51, 'Ι': 0.5,
    'ο': 1.12, 'ό': 1.0, 'Ο': 0.85, 'η': 0.5, 'ή': 0.46, 'Η': 0.5,
    'υ': 1.5, 'ύ': 1.4, 'Υ': 1.55, 'ῦ': 1.7, 'ὐ': 0.93, 'ὺ': 1.78,
    'ῖ': 0.55,
}
VOWEL_SIGN_SIZES = {
    'U': 5.8, 'UU': 3.4, 'I': 2.4, 'II': 0.55, 'O': 1.0,
    'VOCALIC R': 2.6,
}
THAI_VOWELS = {'ุ': 4.24, 'ิ': 1.48, 'ั': 1.27, 'ู': 1.27}
ARABIC_VOWELS = {'ُ': 2.85, 'ِ': 0.83, 'و': 0.6}


def vowel_value(s, previous):
    if s == 'ου':
        return 1.62
    if len(s) != 1:
        return 0.0
    if s in GREEK_VOWELS:
        if s == 'ύ' and previous == 'ο':
            return 3.0
        if s == 'υ' and previous in ('ε', 'ο'):
            return 2.05
        value = GREEK_VOWELS[s]
        return value * 0.6 if previous.isspace() else value
    name = ud.name(s, '')
    if ' VOWEL SIGN ' in name:
        size = VOWEL_SIGN_SIZES.get(name.split(' VOWEL SIGN ')[1], 0.0)
        return size * (0.55 if name.startswith('TAMIL') and size < 5 else 1.0)
    if name in ('DEVANAGARI LETTER U', 'BENGALI LETTER U', 'TELUGU LETTER U'):
        return 3.5
    base, *marks = ud.normalize('NFD', s)
    if base in ('u', 'U'):
        if '\u0308' in marks:
            return 0.35 if previous.isspace() else 1.05
        if any(m in marks for m in '\u0300\u0328\u0309\u031b'):
            return 0.05
        return 0.28 if base == 'u' else 0.35
    if s in 'уУ':
        return 0.2 if previous.isspace() else 0.4
    if s in 'ッュゅゥｯ':
        return 0.7
    if s == 'っ':
        return 0.38
    if s == 'و' and previous.isspace():
        return 0.1
    return THAI_VOWELS.get(s, ARABIC_VOWELS.get(s, 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    if '\ufffd' in token:
        # Decode only tokens that contain a partial UTF-8 character.
        text = prefix.text_prefixes[-1]
        old = prefix.text_prefixes[-2] if prefix.position else ''
        token = text[len(old.rstrip('\ufffd')):].rstrip('\ufffd')
    before = ' ' if token[:1].isspace() else previous
    value = vowel_value(token.strip(), before)
    return (doc, token[-1:] or previous), float(value)

programs.haiku:
"""Layer-0 MLP output unit 5566 (layers.0.mlp.down_proj), as a readable rule.

What it responds to: letter-only tokens with no leading space, i.e. pieces of a word
that are not themselves started by a space (word fragments such as "ck", "ll", "gn",
Cyrillic "р" or "г", and Latin pieces like "BS" or "ft"). Every other token predicts 0.

Within those pieces, the response depends on the spelling:
  - consonant-only pieces (no vowels) respond most: Cyrillic ~0.21, Latin ~0.06,
    other scripts ~0.03;
  - pieces containing a vowel respond about 0 (Latin) or slightly negative (Cyrillic);
  - a piece that follows a token starting with a capital letter gets +0.02.

This is a coarse, concept-level predictor. The large spikes (up to ~1.8) are
context-dependent and token-specific, so the rule explains only about 3-4% of the
variance on random text.
"""
import unicodedata

READS = ()

VOWELS = set("aeiouyäöüéèàâêîôûáíóúãõаеёиоуыэюяəıİşğçñ")


def _script(c):
    o = ord(c)
    if o < 0x250:
        return "latin"
    if 0x370 <= o < 0x400:
        return "greek"
    if 0x400 <= o < 0x530:
        return "cyrillic"
    if 0x3040 <= o < 0x3100 or 0x30A0 <= o < 0x3100:
        return "kana"
    if 0x4E00 <= o < 0xA000:
        return "cjk"
    return "other"


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    letters = len(cur) > 0 and all(unicodedata.category(c).startswith("L") for c in cur)
    if not letters or cur[0] == " ":
        return carry, 0.0
    vowel_free = not any(c.lower() in VOWELS for c in cur)
    script = _script(cur[0])
    if vowel_free:
        value = {"cyrillic": 0.21, "latin": 0.06, "other": 0.03}.get(script, 0.0)
    else:
        value = {"latin": 0.006, "cyrillic": -0.01}.get(script, 0.0)
    prev = prefix.token_strings[-2] if len(prefix) > 1 else " "
    if prev.strip()[:1].isupper():
        value += 0.02
    return carry, float(value)

programs.luna:
"""A conservative token-based approximation of the pronoun response.

The component is usually positive on English first-person and human third-
person pronouns, but its size varies with context; these fixed values are
shrunk to avoid treating every occurrence as a full-strength response.
"""

READS = ()
FIRST_PERSON = {"i", "me", "my", "mine", "myself"}
MASCULINE = {"he", "him", "his", "himself"}
FEMININE = {"she", "her", "hers", "herself"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in FIRST_PERSON:
        return None, 0.525
    if word in MASCULINE:
        return None, 0.645
    if word in FEMININE:
        return None, 0.7875
    return None, 0.0
